import React, { useState, useEffect, useRef } from 'react';
import { AppConfig, PhotoSize } from '../types';
import { getPhotoById } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCameraLinkProps {
  onPhotoReceived: (dataUrl: string) => void;
  onCancel: () => void;
  config: AppConfig;
  selectedSize: PhotoSize;
}

const MobileCameraLink: React.FC<MobileCameraLinkProps> = ({ onPhotoReceived, onCancel, config, selectedSize }) => {
  // Tạo Session ID cố định cho phiên quét này
  const sessionIdRef = useRef<string>(`sid_${Math.random().toString(36).substring(2, 8)}`);
  const [qrUrl, setQrUrl] = useState<string>('');
  const [status, setStatus] = useState<'waiting' | 'error' | 'connected'>('waiting');
  const [pollCount, setPollCount] = useState(0);
  const pollIntervalRef = useRef<any>(null);
  const isSyncingRef = useRef(false);

  useEffect(() => {
    const sid = sessionIdRef.current;
    // Use the specific production URL provided
    const baseUrl = "https://id-photo-booth-pro-926601180918.us-west1.run.app/";
    const scriptUrlEncoded = encodeURIComponent(config.googleScriptUrl || '');

    // Tạo link mobile với đầy đủ tham số
    const mobileLink = `${baseUrl}?mobileSession=${sid}&size=${selectedSize}&surl=${scriptUrlEncoded}`;
    setQrUrl(`https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=${encodeURIComponent(mobileLink)}&color=000000&bgcolor=FFFFFF&margin=2&ecc=M`);

    const checkPhoto = async () => {
      if (isSyncingRef.current || status === 'connected') return;

      try {
        isSyncingRef.current = true;
        setPollCount(prev => prev + 1);

        const photo = await getPhotoById(sid, config.googleScriptUrl);

        if (photo && photo.dataUrl) {
          setStatus('connected');
          if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);
          onPhotoReceived(photo.dataUrl);
        }
      } catch (e) {
        console.error("Polling error:", e);
      } finally {
        isSyncingRef.current = false;
      }
    };

    pollIntervalRef.current = setInterval(checkPhoto, 3000); // Polling mỗi 3 giây
    return () => { if (pollIntervalRef.current) clearInterval(pollIntervalRef.current); };
  }, [selectedSize, config.googleScriptUrl]);

  const handleManualCheck = async () => {
    if (isSyncingRef.current || status === 'connected') return;
    setStatus('waiting');
    isSyncingRef.current = true;
    const photo = await getPhotoById(sessionIdRef.current, config.googleScriptUrl);
    if (photo && photo.dataUrl) {
        setStatus('connected');
        onPhotoReceived(photo.dataUrl);
    } else {
        alert("Chưa tìm thấy ảnh trên Cloud. Hãy đảm bảo điện thoại đã nhấn 'Gửi'.");
    }
    isSyncingRef.current = false;
  };

  return (
    <div className="absolute inset-0 z-[60] bg-slate-950/95 backdrop-blur-xl flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] shadow-2xl max-w-md w-full relative overflow-hidden border border-white/10">
        <div className={`absolute top-0 left-0 w-full h-1.5 transition-colors duration-500 ${status === 'connected' ? 'bg-green-500' : 'bg-brand-500'}`}></div>

        {status === 'connected' ? (
            <div className="py-12 animate-pulse">
                <div className="w-20 h-20 bg-green-500 text-white rounded-full flex items-center justify-center mx-auto mb-6">
                    <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7"></path></svg>
                </div>
                <h2 className="text-2xl font-black text-gray-800 dark:text-white uppercase tracking-tight">Đã nhận ảnh!</h2>
            </div>
        ) : (
            <>
                <div className="mb-6">
                    <h2 className="text-xl font-black text-gray-800 dark:text-white uppercase leading-tight mb-1">Máy ảnh Remote</h2>
                    <div className="flex items-center justify-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                            ID Phiên: <span className="text-brand-600">{sessionIdRef.current}</span>
                        </span>
                    </div>
                </div>

                <div className="relative mx-auto w-52 h-52 mb-8 p-3 bg-white rounded-2xl shadow-inner border border-gray-100 flex items-center justify-center">
                    {qrUrl ? (
                        <img src={qrUrl} alt="QR Code" className="w-full h-full object-contain" />
                    ) : (
                        <div className="animate-spin w-10 h-10 border-4 border-brand-200 border-t-brand-600 rounded-full"></div>
                    )}
                </div>

                <div className="space-y-4">
                    <div className="bg-slate-50 dark:bg-gray-900/50 p-4 rounded-xl border border-slate-100 dark:border-gray-700 text-left">
                         <p className="text-[11px] text-slate-500 dark:text-slate-400 leading-relaxed">
                            1. Quét mã bằng điện thoại.<br/>
                            2. Chụp và nhấn <b>Sử dụng ảnh</b>.<br/>
                            3. Ảnh sẽ xuất hiện ở đây sau vài giây.
                         </p>
                    </div>

                    <div className="flex gap-3">
                        <button onClick={onCancel} className="flex-1 py-3 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-xl font-bold text-[11px] uppercase tracking-wider hover:bg-gray-200">Hủy</button>
                        <button onClick={handleManualCheck} className="flex-[2] py-3 bg-brand-600 text-white rounded-xl font-bold text-[11px] uppercase tracking-wider shadow-lg shadow-brand-500/20">Kiểm tra ngay ({pollCount})</button>
                    </div>
                </div>
            </>
        )}
      </div>
    </div>
  );
};

export default MobileCameraLink;

import React, { useEffect, useState } from 'react';
import { getPhotoById } from '../services/databaseService';
import { SavedPhoto, PhotoSize, AppConfig } from '../types';

interface PhotoViewerProps {
  photoId: string;
  config?: AppConfig; // Optional config for branding
}

const PhotoViewer: React.FC<PhotoViewerProps> = ({ photoId, config }) => {
  const [photo, setPhoto] = useState<SavedPhoto | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Sheet Generation State
  const [isGenerating, setIsGenerating] = useState(false);

  // Determine current URL for QR
  const getCurrentUrl = () => {
    // Use the specific production URL provided
    const baseUrl = "https://id-photo-booth-pro-926601180918.us-west1.run.app/";
    return `${baseUrl}?photoId=${photoId}`;
  };

  useEffect(() => {
    const fetchPhoto = async () => {
      setLoading(true);
      const data = await getPhotoById(photoId);
      if (data) {
        setPhoto(data);
      } else {
        setError('Không tìm thấy ảnh hoặc ảnh đã bị xóa.');
      }
      setLoading(false);
    };
    fetchPhoto();
  }, [photoId]);

  // --- DOWNLOAD HANDLERS ---
  const downloadImage = (dataUrl: string, filename: string) => {
    const link = document.createElement('a');
    link.href = dataUrl;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadSingle = () => {
    if (!photo) return;
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = photo.dataUrl;
    img.crossOrigin = "anonymous";
    img.onload = () => {
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            ctx.drawImage(img, 0, 0);
            const pngData = canvas.toDataURL('image/png');
            downloadImage(pngData, `Photo-${photo.id}-Single.png`);
        }
    };
  };

  // Helper to load image for Canvas
  const loadImage = (src: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error(`Failed to load image`));
        img.src = src;
    });
  };

  const handleDownloadSheet = async () => {
    if (!photo) return;
    setIsGenerating(true);

    try {
        // CONFIG CONSTANTS
        const DPI = 300;
        const MM_TO_PX = DPI / 25.4;
        const SHEET_W = Math.ceil(130 * MM_TO_PX);
        const SHEET_H = Math.ceil(180 * MM_TO_PX);

        const canvas = document.createElement('canvas');
        canvas.width = SHEET_W;
        canvas.height = SHEET_H;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error("Canvas init failed");

        // 1. Fill White Background
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // 2. Prepare Resources (ROBUST LOADING)
        const photoUrl = photo.dataUrl;
        const shopLogoUrl = config?.logoUrl;
        const qrContent = getCurrentUrl();
        // Use 'ecc=H' for High Error Correction to support logo overlay
        const qrApiUrl = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(qrContent)}&color=000000&bgcolor=FFFFFF&margin=0&ecc=H`;

        // Load all images in parallel and wait for them
        const [mainPhotoImg, logoImg, qrImg] = await Promise.all([
            loadImage(photoUrl),
            shopLogoUrl ? loadImage(shopLogoUrl).catch(() => null) : Promise.resolve(null),
            loadImage(qrApiUrl).catch(() => null)
        ]);

        // 3. Draw Photo Grid
        const size = photo.settings.size;
        let cols=2, rows=4, photoW_mm=60, photoH_mm=40, rotated=true, maxOnSheet=8;

        if (size === PhotoSize.SIZE_3X4) {
            cols = 4; rows = 4; photoW_mm = 30; photoH_mm = 40; rotated = false; maxOnSheet = 16;
        } else if (size === PhotoSize.SIZE_5X5) {
            cols = 2; rows = 3; photoW_mm = 50; photoH_mm = 50; rotated = false; maxOnSheet = 6;
        }

        const cellW = photoW_mm * MM_TO_PX;
        const cellH = photoH_mm * MM_TO_PX;
        const gridW = cols * cellW;
        const startY = 5 * MM_TO_PX; // Top margin
        const startX = (canvas.width - gridW) / 2;

        for (let i = 0; i < maxOnSheet; i++) {
            const r = Math.floor(i / cols);
            const c = i % cols;
            const x = startX + c * cellW;
            const y = startY + r * cellH;

            ctx.save();
            ctx.beginPath();
            ctx.rect(x, y, cellW, cellH);
            ctx.clip();

            if (rotated) {
                const cx = x + cellW / 2;
                const cy = y + cellH / 2;
                ctx.translate(cx, cy);
                ctx.rotate(-90 * Math.PI / 180);
                ctx.drawImage(mainPhotoImg, -cellH/2, -cellW/2, cellH, cellW); 
            } else {
                ctx.drawImage(mainPhotoImg, x, y, cellW, cellH);
            }
            ctx.restore();

            // Cut lines
            ctx.strokeStyle = '#d1d5db';
            ctx.lineWidth = 1;
            ctx.setLineDash([15, 15]);
            ctx.strokeRect(x, y, cellW, cellH);
        }

        // 4. Draw Footer (15mm - Compact)
        const footerH = 15 * MM_TO_PX; 
        const footerY = canvas.height - footerH;

        // Background
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, footerY, canvas.width, footerH);

        // Border
        ctx.beginPath();
        ctx.moveTo(0, footerY);
        ctx.lineTo(canvas.width, footerY);
        ctx.strokeStyle = '#000000';
        ctx.lineWidth = 2;
        ctx.setLineDash([]);
        ctx.stroke();

        const padding = 5 * MM_TO_PX;
        const contentY = footerY + footerH / 2;
        let leftOffset = padding;

        // --- DRAW LOGO IN FOOTER ---
        if (logoImg) {
            const logoH = 10 * MM_TO_PX; // Max height 10mm
            const scale = logoH / logoImg.height;
            const logoW = logoImg.width * scale;
            const logoY = contentY - logoH / 2;

            ctx.drawImage(logoImg, leftOffset, logoY, logoW, logoH);
            leftOffset += logoW + (3 * MM_TO_PX); // Add margin after logo
        }

        // --- DRAW TEXT ---
        ctx.textAlign = 'left';

        // Shop Name
        ctx.fillStyle = '#000000';
        const nameSize = 5 * MM_TO_PX;
        ctx.font = `bold ${nameSize}px sans-serif`;
        ctx.textBaseline = 'bottom';
        const shopName = config?.shopName || "ID Photo Booth";
        ctx.fillText(shopName, leftOffset, contentY - (0.5 * MM_TO_PX));

        // Date / Tagline
        ctx.fillStyle = '#4b5563';
        const infoSize = 3.5 * MM_TO_PX;
        ctx.font = `${infoSize}px sans-serif`;
        ctx.textBaseline = 'top';
        const dateStr = new Date(photo.timestamp).toLocaleDateString('vi-VN');
        const footerText = config?.printFooterText || "Ảnh thẻ lấy ngay";
        ctx.fillText(`${footerText} | ${dateStr}`, leftOffset, contentY + (0.5 * MM_TO_PX));

        // --- DRAW QR CODE WITH LOGO OVERLAY ---
        if (qrImg) {
            const qrSize = 12 * MM_TO_PX; 
            const qrX = canvas.width - padding - qrSize;
            const qrY = contentY - qrSize / 2;

            // Draw QR
            ctx.drawImage(qrImg, qrX, qrY, qrSize, qrSize);

            // Draw Mini Logo inside QR
            if (logoImg) {
                const centerLogoSize = qrSize * 0.25; // 25% of QR size
                const centerX = qrX + (qrSize - centerLogoSize) / 2;
                const centerY = qrY + (qrSize - centerLogoSize) / 2;

                // White background box for logo visibility
                ctx.fillStyle = '#ffffff';
                ctx.fillRect(centerX - 1, centerY - 1, centerLogoSize + 2, centerLogoSize + 2);

                // Draw Logo
                ctx.drawImage(logoImg, centerX, centerY, centerLogoSize, centerLogoSize);
            }
        }

        // 5. Download - PNG
        const sheetDataUrl = canvas.toDataURL('image/png');
        downloadImage(sheetDataUrl, `Photo-${photo.id}-Sheet-13x18.png`);

    } catch (e) {
        console.error("Sheet generation failed", e);
        alert("Không thể tạo file in. Vui lòng thử lại.");
    } finally {
        setIsGenerating(false);
    }
  };

  if (loading) return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-gray-50 p-4">
        <div className="w-12 h-12 border-4 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-4"></div>
        <p className="text-gray-500 font-medium animate-pulse">Đang tải ảnh từ Cloud...</p>
    </div>
  );

  if (error || !photo) return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-gray-50 p-6 text-center">
        <div className="w-16 h-16 bg-red-100 text-red-500 rounded-full flex items-center justify-center mb-4 shadow-sm">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
        </div>
        <h2 className="text-xl font-bold text-gray-800 mb-2">Không tìm thấy ảnh</h2>
        <p className="text-gray-600 mb-6 max-w-xs mx-auto">{error}</p>
        <a href="/" className="px-6 py-2.5 bg-gray-800 text-white rounded-xl font-bold hover:bg-black transition shadow-lg">Về trang chủ</a>
    </div>
  );

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-200 p-4 flex flex-col items-center">

       {/* Brand Header */}
       <div className="mb-4 md:mb-6 flex flex-col items-center animate-fadeIn">
          {config?.logoUrl ? (
             <img src={config.logoUrl} alt="Logo" className="h-12 md:h-16 w-auto object-contain mb-2 drop-shadow-sm" />
          ) : (
             <div className="w-10 h-10 md:w-12 md:h-12 bg-brand-600 rounded-2xl flex items-center justify-center text-white font-bold text-lg md:text-xl mb-2 shadow-lg">
               {config?.shopName?.charAt(0) || 'P'}
             </div>
          )}
          <span className="font-bold text-lg md:text-xl text-slate-800 text-center">{config?.shopName || 'ID Photo Booth'}</span>
       </div>

       <div className="max-w-4xl w-full bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row animate-fadeIn">

          {/* Left: Image Preview */}
          <div className="w-full md:w-1/2 bg-slate-100 p-6 md:p-8 flex flex-col items-center justify-center border-b md:border-b-0 md:border-r border-slate-200 relative">
             <div className="absolute top-4 left-4 bg-white/80 backdrop-blur px-3 py-1 rounded-full text-xs font-bold text-slate-500 shadow-sm">
                ID: {photo.id}
             </div>

             <div className="relative shadow-2xl rounded-lg overflow-hidden border-4 border-white transform transition hover:scale-105 duration-300">
                 <img src={photo.dataUrl} className="max-h-[300px] md:max-h-[400px] w-auto object-contain" alt="ID Photo" />
             </div>

             <div className="mt-6 flex flex-wrap justify-center gap-3">
                <span className="px-3 py-1.5 bg-white border border-slate-200 text-slate-600 text-xs font-bold rounded-lg shadow-sm">
                   {photo.settings.size === PhotoSize.SIZE_3X4 ? '3x4 cm' : photo.settings.size === PhotoSize.SIZE_5X5 ? '5x5 cm' : '4x6 cm'}
                </span>
                <span className="px-3 py-1.5 bg-white border border-slate-200 text-slate-600 text-xs font-bold rounded-lg shadow-sm">
                   {new Date(photo.timestamp).toLocaleDateString('vi-VN')}
                </span>
             </div>
          </div>

          {/* Right: Actions */}
          <div className="w-full md:w-1/2 p-6 md:p-8 flex flex-col">
             <div className="mb-6 md:mb-8 text-center md:text-left">
                <h2 className="text-xl md:text-2xl font-black text-slate-800 mb-2">Xin chào! 👋</h2>
                <p className="text-slate-500 text-sm">Ảnh của bạn đã sẵn sàng. Bạn có thể tải về điện thoại hoặc tải file in chất lượng cao để in ấn.</p>
             </div>

             <div className="flex-1 space-y-4">
                 {/* Download Single */}
                 <button 
                    onClick={handleDownloadSingle} 
                    className="group w-full p-4 bg-white border-2 border-slate-100 hover:border-brand-500 hover:bg-brand-50 rounded-2xl transition-all flex items-center gap-4 text-left shadow-sm hover:shadow-md active:scale-95"
                 >
                    <div className="w-10 h-10 md:w-12 md:h-12 rounded-full bg-blue-100 text-brand-600 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
                       <svg className="w-5 h-5 md:w-6 md:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
                    </div>
                    <div>
                       <div className="font-bold text-slate-800 group-hover:text-brand-700 text-sm md:text-base">Tải Ảnh Thẻ (PNG)</div>
                       <div className="text-xs text-slate-400">Ảnh đơn, Chất lượng gốc (HQ)</div>
                    </div>
                 </button>

                 {/* Download Sheet */}
                 <button 
                    onClick={handleDownloadSheet}
                    disabled={isGenerating} 
                    className="group w-full p-4 bg-brand-600 hover:bg-brand-700 rounded-2xl transition-all flex items-center gap-4 text-left shadow-lg shadow-brand-500/30 active:scale-95"
                 >
                    <div className="w-10 h-10 md:w-12 md:h-12 rounded-full bg-white/20 text-white flex items-center justify-center shrink-0">
                        {isGenerating ? (
                           <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        ) : (
                           <svg className="w-5 h-5 md:w-6 md:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
                        )}
                    </div>
                    <div>
                       <div className="font-bold text-white text-sm md:text-base">Tải File In (Sheet 13x18)</div>
                       <div className="text-xs text-brand-100 opacity-80">Đã dàn trang (PNG HQ)</div>
                    </div>
                 </button>
             </div>

             {/* QR Display for Sharing - WITH LOGO */}
             <div className="mt-8 pt-6 border-t border-slate-100 flex flex-col items-center">
                 <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-4">Quét mã để chia sẻ</p>
                 <div className="relative p-2 bg-white rounded-xl shadow-md border border-slate-100">
                    <img 
                      src={`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(getCurrentUrl())}&color=000000&bgcolor=FFFFFF&margin=0&ecc=H`} 
                      className="w-28 h-28 md:w-32 md:h-32"
                      alt="QR"
                    />
                    {/* Embedded Logo in QR */}
                    {config?.logoUrl && (
                        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-8 h-8 bg-white rounded-full p-0.5 shadow-sm border border-slate-100 flex items-center justify-center">
                            <img src={config.logoUrl} className="w-full h-full object-contain rounded-full" alt="Logo" />
                        </div>
                    )}
                 </div>
             </div>
          </div>
       </div>

       {/* Footer - WITH LOGO */}
       <div className="mt-6 text-xs text-slate-400 font-medium text-center pb-8 flex flex-col items-center">
         {config?.logoUrl && (
             <img src={config.logoUrl} className="h-6 w-auto opacity-50 mb-2 grayscale" alt="Logo Footer" />
         )}
         <p>Hotline: {config?.contactPhone}</p>
         <p className="mt-1">© {new Date().getFullYear()} {config?.shopName || 'ID Photo Booth Pro'}</p>
       </div>
    </div>
  );
};

export default PhotoViewer;

import { SavedPhoto, AppConfig } from "../types";
import { getConfig } from "./configService";

const getScriptUrl = (overrideUrl?: string) => {
    if (overrideUrl && overrideUrl.trim() !== '') return overrideUrl.trim();
    const config = getConfig();
    return (config.googleScriptUrl || '').trim();
};

const callAppsScript = async (action: string, payload: any = {}, overrideUrl?: string): Promise<any> => {
    const url = getScriptUrl(overrideUrl);
    if (!url) {
        console.error(`Apps Script Error: Missing URL for [${action}]`);
        return { success: false, error: "Missing URL" };
    }

    try {
        // Thêm timestamp để chống cache kết quả POST
        const body = JSON.stringify({ 
            action, 
            ...payload, 
            _t: Date.now() 
        });

        const response = await fetch(url, {
            method: 'POST',
            body: body,
            headers: { 'Content-Type': 'text/plain;charset=utf-8' }
        });

        if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
        }

        const data = await response.json();
        console.log(`Apps Script [${action}] Response:`, data);
        return data;
    } catch (error) {
        console.error(`Apps Script Network Error [${action}]:`, error);
        return { success: false, error: String(error) };
    }
};

export const savePhotoToCloud = async (photo: SavedPhoto, overrideUrl?: string): Promise<string | null> => {
    const result = await callAppsScript('savePhoto', {
        id: photo.id,
        dataUrl: photo.dataUrl,
        settings: photo.settings
    }, overrideUrl);
    return (result && result.success) ? result.id : null;
};

// Cập nhật: Thêm tham số skipRetry để polling nhanh hơn từ MobileCameraLink
export const getPhotoById = async (id: string, overrideUrl?: string, skipRetry: boolean = false): Promise<SavedPhoto | null> => {
    // Nếu skipRetry = true (dùng cho polling), chỉ thử 1 lần.
    // Nếu false (dùng cho viewer), thử 5 lần để đảm bảo dữ liệu đã đồng bộ.
    const maxRetries = skipRetry ? 1 : 5;

    for (let i = 0; i < maxRetries; i++) {
        const result = await callAppsScript('getPhoto', { id }, overrideUrl);
        if (result && result.success && result.photo) {
            return result.photo as SavedPhoto;
        }

        // Nếu không tìm thấy và được phép retry, đợi 2s rồi thử lại
        if (i < maxRetries - 1) {
            await new Promise(r => setTimeout(r, 2000));
        }
    }
    return null;
};

export const saveAppConfigToCloud = async (config: AppConfig): Promise<boolean> => {
    const result = await callAppsScript('saveConfig', { config });
    return !!(result && result.success);
};

export const getAppConfigFromCloud = async (): Promise<AppConfig | null> => {
    const result = await callAppsScript('getConfig');
    return (result && result.success) ? result.config : null;
};

export const getPhotosFromCloud = async (): Promise<SavedPhoto[]> => {
    const result = await callAppsScript('listPhotos');
    if (result && result.success && Array.isArray(result.photos)) {
        return result.photos;
    }
    return [];
};

export const deletePhotoFromCloud = async (id: string, adminPassword?: string): Promise<boolean> => {
    const result = await callAppsScript('deletePhoto', { id, password: adminPassword });
    return !!(result && result.success);
};

import React, { useState, useEffect, useRef } from 'react';
import { AppConfig, PhotoSize } from '../types';
import { getPhotoById } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCameraLinkProps {
  onPhotoReceived: (dataUrl: string) => void;
  onCancel: () => void;
  config: AppConfig;
  selectedSize: PhotoSize;
}

const MobileCameraLink: React.FC<MobileCameraLinkProps> = ({ onPhotoReceived, onCancel, config, selectedSize }) => {
  // Tạo Session ID cố định cho phiên quét này
  const sessionIdRef = useRef<string>(`sid_${Math.random().toString(36).substring(2, 8)}`);
  const [qrUrl, setQrUrl] = useState<string>('');
  const [status, setStatus] = useState<'waiting' | 'found' | 'downloading'>('waiting');
  const [pollCount, setPollCount] = useState(0);

  // Refs để quản lý vòng lặp polling an toàn
  const isMountedRef = useRef(true);
  const timeoutRef = useRef<any>(null);

  // 1. Khởi tạo QR Code
  useEffect(() => {
    const sid = sessionIdRef.current;
    // URL Production
    const baseUrl = "https://id-photo-booth-pro-926601180918.us-west1.run.app/";
    const scriptUrlEncoded = encodeURIComponent(config.googleScriptUrl || '');

    // Tạo link mobile với đầy đủ tham số
    const mobileLink = `${baseUrl}?mobileSession=${sid}&size=${selectedSize}&surl=${scriptUrlEncoded}`;
    setQrUrl(`https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=${encodeURIComponent(mobileLink)}&color=000000&bgcolor=FFFFFF&margin=2&ecc=M`);

    return () => {
        isMountedRef.current = false;
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [selectedSize, config.googleScriptUrl]);

  // 2. Logic Polling (Hỏi server liên tục)
  const pollForPhoto = async () => {
      if (!isMountedRef.current) return;

      try {
          setPollCount(prev => prev + 1);
          // skipRetry = true: Chỉ hỏi 1 lần rồi trả về ngay để UI không bị đơ
          const photo = await getPhotoById(sessionIdRef.current, config.googleScriptUrl, true);

          if (photo && photo.dataUrl) {
              if (!isMountedRef.current) return;
              setStatus('found');

              // Giả lập delay nhỏ để người dùng thấy hiệu ứng "Đã tìm thấy"
              setTimeout(() => {
                  if (isMountedRef.current) {
                      onPhotoReceived(photo.dataUrl);
                  }
              }, 1000);
              return; // Dừng polling
          }
      } catch (e) {
          console.error("Polling error (silent):", e);
      }

      // Nếu chưa thấy ảnh, đợi 2.5 giây rồi hỏi lại (Đệ quy)
      if (isMountedRef.current) {
          timeoutRef.current = setTimeout(pollForPhoto, 2500);
      }
  };

  // Bắt đầu polling khi component mount
  useEffect(() => {
      pollForPhoto();
      return () => {
          if (timeoutRef.current) clearTimeout(timeoutRef.current);
      };
  }, []);

  return (
    <div className="absolute inset-0 z-[60] bg-slate-950/95 backdrop-blur-xl flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] shadow-2xl max-w-md w-full relative overflow-hidden border border-white/10">
        <div className={`absolute top-0 left-0 w-full h-1.5 transition-colors duration-500 ${status === 'found' ? 'bg-green-500' : 'bg-brand-500'}`}></div>

        {status === 'found' ? (
            <div className="py-12 animate-pulse flex flex-col items-center">
                <div className="w-24 h-24 bg-green-500 text-white rounded-full flex items-center justify-center mb-6 shadow-green-500/50 shadow-lg">
                    <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7"></path></svg>
                </div>
                <h2 className="text-2xl font-black text-gray-800 dark:text-white uppercase tracking-tight">Đã nhận ảnh!</h2>
                <p className="text-gray-500 mt-2">Đang tải xuống máy tính...</p>
            </div>
        ) : (
            <>
                <div className="mb-6">
                    <h2 className="text-xl font-black text-gray-800 dark:text-white uppercase leading-tight mb-1">Kết nối Điện Thoại</h2>
                    <div className="flex items-center justify-center gap-2">
                        <span className="relative flex h-3 w-3">
                          <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-brand-400 opacity-75"></span>
                          <span className="relative inline-flex rounded-full h-3 w-3 bg-brand-500"></span>
                        </span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                            Đang chờ ảnh từ Cloud... ({pollCount})
                        </span>
                    </div>
                </div>

                <div className="relative mx-auto w-56 h-56 mb-8 p-3 bg-white rounded-2xl shadow-inner border border-gray-100 flex items-center justify-center">
                    {qrUrl ? (
                        <img src={qrUrl} alt="QR Code" className="w-full h-full object-contain" />
                    ) : (
                        <div className="animate-spin w-10 h-10 border-4 border-brand-200 border-t-brand-600 rounded-full"></div>
                    )}

                    {/* Hướng dẫn visual */}
                    <div className="absolute -bottom-12 left-1/2 -translate-x-1/2 w-max">
                        <div className="flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-slate-700 rounded-full text-xs font-bold text-slate-600 dark:text-slate-300 shadow-sm">
                            <span className="text-lg">📸</span> Quét mã để chụp
                        </div>
                    </div>
                </div>

                <div className="space-y-4 mt-8">
                    <div className="bg-slate-50 dark:bg-gray-900/50 p-4 rounded-xl border border-slate-100 dark:border-gray-700 text-left">
                         <div className="flex gap-3 mb-2">
                            <div className="w-6 h-6 rounded-full bg-brand-100 text-brand-600 flex items-center justify-center font-bold text-xs shrink-0">1</div>
                            <p className="text-xs text-slate-600 dark:text-slate-300 pt-0.5">Dùng điện thoại quét mã QR ở trên.</p>
