                    </div>

                    <button onClick={onCancel} className="w-full py-3 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-xl font-bold text-[11px] uppercase tracking-wider hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors">
