                isAutoCaptureEnabled={isAutoCaptureEnabled}
                validationStatus={validationStatus}
                countdown={countdown}
                isCapturing={isCapturing}
                onAutoCaptureToggle={() => setIsAutoCaptureEnabled(!isAutoCaptureEnabled)}
                onCaptureClick={() => setCountdown(3)}
                onMobileLink={() => setSelectedDeviceId('mobile-link')}
                config={config}
            />
        </div>
      )}

      <canvas ref={canvasRef} className="hidden" />
      <canvas ref={analysisCanvasRef} className="hidden" />
      <style>{`@keyframes scan { 0% { top: 0%; opacity: 0; } 10% { opacity: 1; } 90% { opacity: 1; } 100% { top: 100%; opacity: 0; } }`}</style>
    </div>
  );
};

export default CameraCapture;

import React, { useRef, useState, useEffect, useCallback, useMemo } from 'react';
import { PhotoSize, AppConfig } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';
import { savePhotoToCloud } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCaptureClientProps {
  sessionId: string;
  config: AppConfig;
  initialSize?: PhotoSize;
}

type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

const SHUTTER_SOUND = "data:audio/mp3;base64,";

const MobileCaptureClient: React.FC<MobileCaptureClientProps> = ({ sessionId, config, initialSize = PhotoSize.SIZE_4X6 }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null);
  const shutterAudioRef = useRef<HTMLAudioElement | null>(null);
  const analysisIntervalRef = useRef<any>(null);
  const isAnalyzingRef = useRef(false);
  const hasAutoCapturedRef = useRef(false);
  const lastSpokenRef = useRef<string>('');

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>(t('capture.label.processing', config));
  const [instruction, setInstruction] = useState<string>('');
  const [cameraError, setCameraError] = useState('');
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  // Default to TRUE for Auto Capture
  const [isAutoCaptureEnabled, setIsAutoCaptureEnabled] = useState(true);

  // --- Voice Synthesis Logic ---
  const speak = (text: string, force: boolean = false) => {
    if (!text || (!force && lastSpokenRef.current === text)) return;

    // Mobile often requires user interaction first, but we attempt anyway
    if (force || window.speechSynthesis.speaking) window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = config.language === 'en' ? 'en-US' : 'vi-VN'; 

    const voices = window.speechSynthesis.getVoices();
    const voice = voices.find(v => v.lang.startsWith(utterance.lang));
    if (voice) utterance.voice = voice;

    // Mobile quirk: high rate helps responsiveness
    utterance.rate = 1.0; 

    window.speechSynthesis.speak(utterance);
    lastSpokenRef.current = text;
  };

  // Speak instructions on change
  useEffect(() => {
     if (countdown !== null) return; 
     if (instruction) {
         if (validationStatus === 'valid') { 
            if (lastSpokenRef.current !== 'ok') { 
                speak(t('capture.msg.valid', config), true); 
                lastSpokenRef.current = 'ok'; 
            } 
         } else { 
            speak(instruction); 
         }
     }
  }, [instruction, validationStatus, countdown]);

  const startCamera = async (mode: 'user' | 'environment') => {
    if (stream) stream.getTracks().forEach(track => track.stop());
    const constraints: MediaStreamConstraints = { video: { facingMode: mode, width: { ideal: 1920 }, height: { ideal: 1080 } } };
    try {
      const s = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(s);
      if (videoRef.current) videoRef.current.srcObject = s;
    } catch (e) {
      setCameraError('Máy ảnh chưa được cấp quyền.');
    }
  };

  useEffect(() => {
    startCamera(facingMode);
    shutterAudioRef.current = new Audio(SHUTTER_SOUND);
    return () => {
      if (stream) stream.getTracks().forEach(t => t.stop());
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
      window.speechSynthesis.cancel();
    };
  }, [facingMode]);

  useEffect(() => {
    if (stream && !countdown && !capturedImage) {
      analysisIntervalRef.current = setInterval(performAIAnalysis, 3000);
    } else {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    }
    return () => { if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current); };
  }, [stream, countdown, capturedImage]);

  useEffect(() => {
    if (isAutoCaptureEnabled && validationStatus === 'valid' && !hasAutoCapturedRef.current && countdown === null && !capturedImage) {
      hasAutoCapturedRef.current = true;
      setCountdown(3);
    } else if (validationStatus !== 'valid') {
      hasAutoCapturedRef.current = false;
    }
  }, [validationStatus, isAutoCaptureEnabled, countdown, capturedImage]);

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current) return;
    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (video.readyState === 4 && ctx) {
        const crop = getCropDimensions(video.videoWidth, video.videoHeight);
        canvas.width = 240; canvas.height = 360;
        if (facingMode === 'user') { ctx.translate(canvas.width, 0); ctx.scale(-1, 1); }
        ctx.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        const result = await analyzeIDPhotoFrame(canvas.toDataURL('image/jpeg', 0.5));
        if (!result.faceDetected) {
            setValidationStatus('searching'); setFeedbackMessage(t('capture.msg.no_face', config)); setInstruction(t('capture.msg.move_in', config));
        } else if (result.isCompliant) {
            setValidationStatus('valid'); setFeedbackMessage(t('capture.status.valid', config)); setInstruction(t('capture.msg.valid', config));
        } else {
            setValidationStatus('adjusting'); setFeedbackMessage(result.feedback || t('capture.status.adjusting', config)); setInstruction(result.instruction || '');
        }
      }
    } catch (err) {} finally { isAnalyzingRef.current = false; }
  };

  const getCropDimensions = (sourceW: number, sourceH: number) => {
    let targetRatio = initialSize === PhotoSize.SIZE_5X5 ? 1 : (initialSize === PhotoSize.SIZE_3X4 ? 3/4 : 2/3);
    const sourceRatio = sourceW / sourceH;
    let cropW, cropH, startX, startY;
    if (sourceRatio > targetRatio) { cropH = sourceH; cropW = cropH * targetRatio; startX = (sourceW - cropW) / 2; startY = 0; }
    else { cropW = sourceW; cropH = cropW / targetRatio; startX = 0; startY = (sourceH - cropH) * 0.5; }
    return { x: Math.floor(startX), y: Math.floor(startY), w: Math.floor(cropW), h: Math.floor(cropH) };
  };

  const captureFrame = useCallback(() => {
    if (shutterAudioRef.current) shutterAudioRef.current.play().catch(() => {});
    if (!videoRef.current || !canvasRef.current) return;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const crop = getCropDimensions(video.videoWidth, video.videoHeight);

    canvas.height = 1000;
    canvas.width = Math.floor(1000 * (crop.w/crop.h));

    if (facingMode === 'user') { ctx?.translate(canvas.width, 0); ctx?.scale(-1, 1); }
    ctx?.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);

    setCapturedImage(canvas.toDataURL('image/jpeg', 0.8));
  }, [facingMode, initialSize]);

  useEffect(() => {
    if (countdown === null) return;
    if (countdown > 0) {
        speak(countdown.toString(), true); // Speak count
        const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
        return () => clearTimeout(timer);
    } else {
        captureFrame();
        setCountdown(null);
    }
  }, [countdown, captureFrame]);

  const handleUpload = async () => {
    if (!capturedImage || !sessionId) return;
    setIsUploading(true);
    try {
        const resultId = await savePhotoToCloud({
            id: sessionId,
            dataUrl: capturedImage,
            timestamp: Date.now(),
            settings: { size: initialSize, background: 'original' as any, beauty: {} as any, printQuantity: 1 }
        }, config.googleScriptUrl);

        if (resultId) setIsCompleted(true);
        else alert('Đồng bộ thất bại. Vui lòng thử lại.');
    } catch (e) { 
        alert('Lỗi kết nối Cloud.'); 
    } finally { 
        setIsUploading(false); 
    }
  };

  const topMarginPercent = useMemo(() => initialSize === PhotoSize.SIZE_3X4 ? 7.5 : initialSize === PhotoSize.SIZE_5X5 ? 6 : 7, [initialSize]);
  const overlayColor = validationStatus === 'valid' ? '#22c55e' : validationStatus === 'adjusting' ? '#facc15' : '#ef4444';

  if (isCompleted) {
    return (
        <div className="h-[100dvh] bg-brand-600 flex flex-col items-center justify-center text-white p-8 text-center animate-fadeIn">
            <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mb-8 shadow-2xl">
                <svg className="w-10 h-10 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
            </div>
            <h2 className="text-2xl font-black mb-4 uppercase">Gửi thành công!</h2>
            <p className="opacity-90">ID phiên: <span className="font-mono bg-black/20 px-2 rounded">{sessionId}</span></p>
            <p className="mt-4 opacity-80 text-sm">Hãy quay lại màn hình máy tính.</p>
        </div>
    );
  }

  return (
    <div className="h-[100dvh] bg-black flex flex-col relative overflow-hidden touch-none py-safe">
        <div className="absolute top-0 left-0 right-0 p-4 z-50 flex flex-col items-center pointer-events-none">
            {!capturedImage && (
                <div className={`px-6 py-4 rounded-3xl backdrop-blur-md border-2 transition-all duration-300 text-center shadow-lg flex flex-col ${validationStatus === 'valid' ? 'bg-green-600/90 border-green-400' : 'bg-black/60 border-white/20'}`}>
                    <span className="text-white font-black text-xs uppercase tracking-widest mb-1 block">{feedbackMessage}</span>
                    <span className="text-white text-lg font-bold leading-tight px-2">{instruction}</span>
                </div>
            )}
            <div className="mt-2 text-[8px] text-white/40 font-mono">Phiên: {sessionId}</div>
        </div>

        <div className="flex-1 relative flex items-center justify-center bg-gray-900 overflow-hidden">
            {cameraError ? (
                <div className="text-white text-center p-6 bg-black/80 rounded-2xl border border-red-500 m-4">
                    <p className="font-bold">{cameraError}</p>
                    <button onClick={() => window.location.reload()} className="mt-4 px-6 py-2 bg-white text-black rounded-full font-bold">Thử lại</button>
                </div>
            ) : capturedImage ? (
                <div className="relative h-full w-full flex items-center justify-center p-4">
                    <img src={capturedImage} className="max-h-full max-w-full rounded shadow-2xl" alt="Preview" />
                </div>
            ) : (
                <>
                    <video ref={videoRef} autoPlay playsInline className={`absolute inset-0 w-full h-full object-cover ${facingMode === 'user' ? 'transform -scale-x-100' : ''}`} />
                    <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none z-20">
                        <defs><mask id="m"><rect x="0" y="0" width="100" height="100" fill="white" /><ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="black" /></mask></defs>
                        <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#m)" />
                        <ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="none" stroke={overlayColor} strokeWidth="0.5" strokeDasharray="2,2" />
                    </svg>
                </>
            )}

            {countdown !== null && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/40 z-[100] backdrop-blur-sm">
                    <span className="text-9xl font-black text-white animate-ping">{countdown}</span>
                </div>
            )}
        </div>

        <div className="bg-black/95 p-6 pb-12 z-50 flex flex-col items-center gap-4">
            {capturedImage ? (
                <div className="flex w-full gap-4 max-w-sm">
                    <button onClick={() => setCapturedImage(null)} disabled={isUploading} className="flex-1 py-4 bg-gray-800 text-white rounded-2xl font-bold uppercase text-xs">Chụp lại</button>
                    <button onClick={handleUpload} disabled={isUploading} className="flex-[2] py-4 bg-brand-600 text-white rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 uppercase text-xs">
                        {isUploading ? "Đang gửi..." : "Sử dụng ảnh này"}
                    </button>
                </div>
            ) : (
                <div className="flex items-center justify-between w-full max-w-sm px-4">
                    <button onClick={() => setFacingMode(f => f === 'user' ? 'environment' : 'user')} className="w-14 h-14 rounded-full bg-white/20 flex items-center justify-center text-white backdrop-blur border border-white/10 active:bg-white/30 transition-all">
                        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                    </button>

                    <button onClick={() => setCountdown(3)} disabled={countdown !== null} className={`w-24 h-24 rounded-full border-4 flex items-center justify-center transition-all ${validationStatus === 'valid' ? 'border-green-500 bg-white shadow-[0_0_30px_rgba(34,197,94,0.5)]' : 'border-gray-500 bg-gray-700'}`}>
                        <div className={`w-20 h-20 rounded-full transition-colors ${validationStatus === 'valid' ? 'bg-green-600' : 'bg-gray-500'}`}></div>
                    </button>

                    <button onClick={() => setIsAutoCaptureEnabled(!isAutoCaptureEnabled)} className={`w-14 h-14 rounded-xl flex flex-col items-center justify-center border-2 transition-all active:scale-95 ${isAutoCaptureEnabled ? 'bg-brand-600 border-brand-400 text-white shadow-lg shadow-brand-500/50' : 'bg-gray-800 border-gray-600 text-gray-500'}`}>
                        <svg className={`w-6 h-6 mb-0.5 ${isAutoCaptureEnabled ? 'animate-pulse' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                        <span className="text-[9px] font-black uppercase">Auto</span>
                    </button>
                </div>
            )}
        </div>
        <canvas ref={canvasRef} className="hidden" />
        <canvas ref={analysisCanvasRef} className="hidden" />
    </div>
  );
};

export default MobileCaptureClient;

import React, { useState, useEffect, useRef } from 'react';
import { AppConfig, PhotoSize } from '../types';
import { getPhotoById } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCameraLinkProps {
  onPhotoReceived: (dataUrl: string) => void;
  onCancel: () => void;
  config: AppConfig;
  selectedSize: PhotoSize;
}

const MobileCameraLink: React.FC<MobileCameraLinkProps> = ({ onPhotoReceived, onCancel, config, selectedSize }) => {
  // Tạo Session ID cố định cho phiên quét này
  const sessionIdRef = useRef<string>(`sid_${Math.random().toString(36).substring(2, 8)}`);
  const [qrUrl, setQrUrl] = useState<string>('');
  const [status, setStatus] = useState<'waiting' | 'found' | 'downloading'>('waiting');
  const [pollCount, setPollCount] = useState(0);

  // Refs để quản lý vòng lặp polling an toàn
  const isMountedRef = useRef(true);
  const timeoutRef = useRef<any>(null);

  // 1. Khởi tạo QR Code
  useEffect(() => {
    const sid = sessionIdRef.current;

    // Auto-detect base URL (Strip query params)
    let baseUrl = window.location.href.split('?')[0];

    // Fallback if running in strict constrained environments or if dynamic detection fails
    if (!baseUrl || baseUrl === 'about:blank') {
        baseUrl = "https://id-photo-booth-pro-926601180918.us-west1.run.app/";
    }

    const scriptUrlEncoded = encodeURIComponent(config.googleScriptUrl || '');

    // Tạo link mobile với đầy đủ tham số
    const mobileLink = `${baseUrl}?mobileSession=${sid}&size=${selectedSize}&surl=${scriptUrlEncoded}`;
    setQrUrl(`https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=${encodeURIComponent(mobileLink)}&color=000000&bgcolor=FFFFFF&margin=2&ecc=M`);

    return () => {
        isMountedRef.current = false;
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [selectedSize, config.googleScriptUrl]);

  // 2. Logic Polling (Hỏi server liên tục)
  const pollForPhoto = async () => {
      if (!isMountedRef.current) return;

      try {
          setPollCount(prev => prev + 1);
          // skipRetry = true: Chỉ hỏi 1 lần rồi trả về ngay để UI không bị đơ
          const photo = await getPhotoById(sessionIdRef.current, config.googleScriptUrl, true);

          if (photo && photo.dataUrl) {
              if (!isMountedRef.current) return;
              setStatus('found');

              // Giả lập delay nhỏ để người dùng thấy hiệu ứng "Đã tìm thấy"
              setTimeout(() => {
                  if (isMountedRef.current) {
                      onPhotoReceived(photo.dataUrl);
                  }
              }, 1000);
              return; // Dừng polling
          }
      } catch (e) {
          console.error("Polling error (silent):", e);
      }

      // Nếu chưa thấy ảnh, đợi 2.5 giây rồi hỏi lại (Đệ quy)
      if (isMountedRef.current) {
          timeoutRef.current = setTimeout(pollForPhoto, 2500);
      }
  };

  // Bắt đầu polling khi component mount
  useEffect(() => {
      pollForPhoto();
      return () => {
          if (timeoutRef.current) clearTimeout(timeoutRef.current);
      };
  }, []);

  return (
    <div className="absolute inset-0 z-[60] bg-slate-950/95 backdrop-blur-xl flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] shadow-2xl max-w-md w-full relative overflow-hidden border border-white/10">
        <div className={`absolute top-0 left-0 w-full h-1.5 transition-colors duration-500 ${status === 'found' ? 'bg-green-500' : 'bg-brand-500'}`}></div>

        {status === 'found' ? (
            <div className="py-12 animate-pulse flex flex-col items-center">
                <div className="w-24 h-24 bg-green-500 text-white rounded-full flex items-center justify-center mb-6 shadow-green-500/50 shadow-lg">
                    <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7"></path></svg>
                </div>
                <h2 className="text-2xl font-black text-gray-800 dark:text-white uppercase tracking-tight">Đã nhận ảnh!</h2>
                <p className="text-gray-500 mt-2">Đang tải xuống máy tính...</p>
            </div>
        ) : (
            <>
                <div className="mb-6">
                    <h2 className="text-xl font-black text-gray-800 dark:text-white uppercase leading-tight mb-1">Kết nối Điện Thoại</h2>
                    <div className="flex items-center justify-center gap-2">
                        <span className="relative flex h-3 w-3">
                          <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-brand-400 opacity-75"></span>
                          <span className="relative inline-flex rounded-full h-3 w-3 bg-brand-500"></span>
                        </span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                            Đang chờ ảnh từ Cloud... ({pollCount})
                        </span>
                    </div>
                </div>

                <div className="relative mx-auto w-56 h-56 mb-8 p-3 bg-white rounded-2xl shadow-inner border border-gray-100 flex items-center justify-center">
                    {qrUrl ? (
                        <img src={qrUrl} alt="QR Code" className="w-full h-full object-contain" />
                    ) : (
                        <div className="animate-spin w-10 h-10 border-4 border-brand-200 border-t-brand-600 rounded-full"></div>
                    )}

                    {/* Hướng dẫn visual */}
                    <div className="absolute -bottom-12 left-1/2 -translate-x-1/2 w-max">
                        <div className="flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-slate-700 rounded-full text-xs font-bold text-slate-600 dark:text-slate-300 shadow-sm">
                            <span className="text-lg">📸</span> Quét mã để chụp
                        </div>
                    </div>
                </div>

                <div className="space-y-4 mt-8">
                    <div className="bg-slate-50 dark:bg-gray-900/50 p-4 rounded-xl border border-slate-100 dark:border-gray-700 text-left">
                         <div className="flex gap-3 mb-2">
                            <div className="w-6 h-6 rounded-full bg-brand-100 text-brand-600 flex items-center justify-center font-bold text-xs shrink-0">1</div>
                            <p className="text-xs text-slate-600 dark:text-slate-300 pt-0.5">Dùng điện thoại quét mã QR ở trên.</p>
                         </div>
                         <div className="flex gap-3 mb-2">
                            <div className="w-6 h-6 rounded-full bg-brand-100 text-brand-600 flex items-center justify-center font-bold text-xs shrink-0">2</div>
                            <p className="text-xs text-slate-600 dark:text-slate-300 pt-0.5">Chụp ảnh selfie hoặc tải ảnh lên.</p>
                         </div>
                         <div className="flex gap-3">
                            <div className="w-6 h-6 rounded-full bg-brand-100 text-brand-600 flex items-center justify-center font-bold text-xs shrink-0">3</div>
                            <p className="text-xs text-slate-600 dark:text-slate-300 pt-0.5">Nhấn "Sử dụng ảnh", máy tính sẽ tự nhận.</p>
                         </div>
                    </div>

                    <button onClick={onCancel} className="w-full py-3 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-xl font-bold text-[11px] uppercase tracking-wider hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors">
                        Quay lại Webcam
                    </button>
                </div>
            </>
        )}
      </div>
    </div>
  );
};

export default MobileCameraLink;

import React, { useRef, useState, useEffect, useCallback, useMemo } from 'react';
import { PhotoSize, AppConfig } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';
import { savePhotoToCloud } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCaptureClientProps {
  sessionId: string;
  config: AppConfig;
  initialSize?: PhotoSize;
}

type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

const SHUTTER_SOUND = "data:audio/mp3;base64,";

const MobileCaptureClient: React.FC<MobileCaptureClientProps> = ({ sessionId, config, initialSize = PhotoSize.SIZE_4X6 }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null);
  const shutterAudioRef = useRef<HTMLAudioElement | null>(null);
  const analysisIntervalRef = useRef<any>(null);
  const isAnalyzingRef = useRef(false);
  const hasAutoCapturedRef = useRef(false);
  const lastSpokenRef = useRef<string>('');

  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>(t('capture.label.processing', config));
  const [instruction, setInstruction] = useState<string>('');
  const [cameraError, setCameraError] = useState('');
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  // Default to TRUE for Auto Capture
  const [isAutoCaptureEnabled, setIsAutoCaptureEnabled] = useState(true);

  // --- Voice Synthesis Logic ---
  const speak = (text: string, force: boolean = false) => {
    if (!text || (!force && lastSpokenRef.current === text)) return;
    if (force || window.speechSynthesis.speaking) window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = config.language === 'en' ? 'en-US' : 'vi-VN'; 
    const voices = window.speechSynthesis.getVoices();
    const voice = voices.find(v => v.lang.startsWith(utterance.lang));
    if (voice) utterance.voice = voice;
    utterance.rate = 1.0; 
    window.speechSynthesis.speak(utterance);
    lastSpokenRef.current = text;
  };

  // Speak instructions on change
  useEffect(() => {
     if (countdown !== null) return; 
     if (instruction) {
         if (validationStatus === 'valid') { 
            if (lastSpokenRef.current !== 'ok') { 
                speak(t('capture.msg.valid', config), true); 
                lastSpokenRef.current = 'ok'; 
            } 
         } else { 
            speak(instruction); 
         }
     }
  }, [instruction, validationStatus, countdown]);

  // Robust Camera Initialization
  useEffect(() => {
    let currentStream: MediaStream | null = null;
    let isMounted = true;

    const initCamera = async () => {
        try {
            // Cleanup previous if any
            if (currentStream) {
                (currentStream as MediaStream).getTracks().forEach(t => t.stop());
            }

            setCameraError(''); 

            // Try constraints - Relaxed for better mobile compatibility
            const constraints: MediaStreamConstraints = {
                audio: false,
                video: {
                    facingMode: facingMode,
                    width: { ideal: 1280 }, // Ideal 720p/1080p but accept others
                    height: { ideal: 720 }
                }
            };

            const s = await navigator.mediaDevices.getUserMedia(constraints);

            if (!isMounted) {
                s.getTracks().forEach(t => t.stop());
                return;
            }

            currentStream = s;

            if (videoRef.current) {
                videoRef.current.srcObject = s;
                // Important for iOS: Explicit play
                videoRef.current.onloadedmetadata = () => {
                   if(videoRef.current) videoRef.current.play().catch(e => console.log("Auto-play prevented:", e));
                };
            }
        } catch (err: any) {
            console.error("Camera Init Error:", err);
            if (isMounted) {
                 if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
                    setCameraError('Vui lòng CẤP QUYỀN CAMERA trong cài đặt trình duyệt.');
                 } else if (err.name === 'NotFoundError' || err.name === 'DevicesNotFoundError') {
                    setCameraError('Không tìm thấy Camera trên thiết bị này.');
                 } else if (err.name === 'NotReadableError' || err.name === 'TrackStartError') {
                     setCameraError('Camera đang bị ứng dụng khác chiếm dụng. Hãy đóng bớt các tab/app.');
                 } else {
                    setCameraError(`Lỗi Camera: ${err.message || 'Không xác định'}`);
                 }
            }
        }
    };

    initCamera();
    shutterAudioRef.current = new Audio(SHUTTER_SOUND);

    return () => {
        isMounted = false;
        if (currentStream) {
            currentStream.getTracks().forEach(t => t.stop());
        }
        if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
        window.speechSynthesis.cancel();
    };
  }, [facingMode]);

  useEffect(() => {
    // Check if videoRef has stream before starting analysis
    if (videoRef.current && videoRef.current.srcObject && !countdown && !capturedImage) {
      analysisIntervalRef.current = setInterval(performAIAnalysis, 3000);
    } else {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    }
    return () => { if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current); };
  }, [countdown, capturedImage, videoRef.current?.srcObject]); // Depend on srcObject presence

  useEffect(() => {
    if (isAutoCaptureEnabled && validationStatus === 'valid' && !hasAutoCapturedRef.current && countdown === null && !capturedImage) {
      hasAutoCapturedRef.current = true;
      setCountdown(3);
    } else if (validationStatus !== 'valid') {
      hasAutoCapturedRef.current = false;
    }
  }, [validationStatus, isAutoCaptureEnabled, countdown, capturedImage]);

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current) return;
    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (video.readyState === 4 && ctx) {
        const crop = getCropDimensions(video.videoWidth, video.videoHeight);
        canvas.width = 240; canvas.height = 360;
        if (facingMode === 'user') { ctx.translate(canvas.width, 0); ctx.scale(-1, 1); }
        ctx.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        const result = await analyzeIDPhotoFrame(canvas.toDataURL('image/jpeg', 0.5));
        if (!result.faceDetected) {
            setValidationStatus('searching'); setFeedbackMessage(t('capture.msg.no_face', config)); setInstruction(t('capture.msg.move_in', config));
        } else if (result.isCompliant) {
            setValidationStatus('valid'); setFeedbackMessage(t('capture.status.valid', config)); setInstruction(t('capture.msg.valid', config));
        } else {
            setValidationStatus('adjusting'); setFeedbackMessage(result.feedback || t('capture.status.adjusting', config)); setInstruction(result.instruction || '');
        }
      }
    } catch (err) {} finally { isAnalyzingRef.current = false; }
  };

  const getCropDimensions = (sourceW: number, sourceH: number) => {
    let targetRatio = initialSize === PhotoSize.SIZE_5X5 ? 1 : (initialSize === PhotoSize.SIZE_3X4 ? 3/4 : 2/3);
    const sourceRatio = sourceW / sourceH;
    let cropW, cropH, startX, startY;
    if (sourceRatio > targetRatio) { cropH = sourceH; cropW = cropH * targetRatio; startX = (sourceW - cropW) / 2; startY = 0; }
    else { cropW = sourceW; cropH = cropW / targetRatio; startX = 0; startY = (sourceH - cropH) * 0.5; }
    return { x: Math.floor(startX), y: Math.floor(startY), w: Math.floor(cropW), h: Math.floor(cropH) };
  };

  const captureFrame = useCallback(() => {
    if (shutterAudioRef.current) shutterAudioRef.current.play().catch(() => {});
    if (!videoRef.current || !canvasRef.current) return;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const crop = getCropDimensions(video.videoWidth, video.videoHeight);

    canvas.height = 1000;
    canvas.width = Math.floor(1000 * (crop.w/crop.h));

    if (facingMode === 'user') { ctx?.translate(canvas.width, 0); ctx?.scale(-1, 1); }
    ctx?.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);

    setCapturedImage(canvas.toDataURL('image/jpeg', 0.8));
  }, [facingMode, initialSize]);

  useEffect(() => {
    if (countdown === null) return;
    if (countdown > 0) {
        speak(countdown.toString(), true); // Speak count
        const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
        return () => clearTimeout(timer);
    } else {
        captureFrame();
        setCountdown(null);
    }
  }, [countdown, captureFrame]);

  const handleUpload = async () => {
    if (!capturedImage || !sessionId) return;
    setIsUploading(true);
    try {
        const resultId = await savePhotoToCloud({
            id: sessionId,
            dataUrl: capturedImage,
            timestamp: Date.now(),
            settings: { size: initialSize, background: 'original' as any, beauty: {} as any, printQuantity: 1 }
        }, config.googleScriptUrl);

        if (resultId) setIsCompleted(true);
        else alert('Đồng bộ thất bại. Vui lòng thử lại.');
    } catch (e) { 
        alert('Lỗi kết nối Cloud.'); 
    } finally { 
        setIsUploading(false); 
    }
  };

  const topMarginPercent = useMemo(() => initialSize === PhotoSize.SIZE_3X4 ? 7.5 : initialSize === PhotoSize.SIZE_5X5 ? 6 : 7, [initialSize]);
  const overlayColor = validationStatus === 'valid' ? '#22c55e' : validationStatus === 'adjusting' ? '#facc15' : '#ef4444';

  if (isCompleted) {
    return (
        <div className="h-[100dvh] bg-brand-600 flex flex-col items-center justify-center text-white p-8 text-center animate-fadeIn">
            <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mb-8 shadow-2xl">
                <svg className="w-10 h-10 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
            </div>
            <h2 className="text-2xl font-black mb-4 uppercase">Gửi thành công!</h2>
            <p className="opacity-90">ID phiên: <span className="font-mono bg-black/20 px-2 rounded">{sessionId}</span></p>
            <p className="mt-4 opacity-80 text-sm">Hãy quay lại màn hình máy tính.</p>
        </div>
    );
  }

  return (
    <div className="h-[100dvh] bg-black flex flex-col relative overflow-hidden touch-none py-safe">
        <div className="absolute top-0 left-0 right-0 p-4 z-50 flex flex-col items-center pointer-events-none">
            {!capturedImage && (
                <div className={`px-6 py-4 rounded-3xl backdrop-blur-md border-2 transition-all duration-300 text-center shadow-lg flex flex-col ${validationStatus === 'valid' ? 'bg-green-600/90 border-green-400' : 'bg-black/60 border-white/20'}`}>
                    <span className="text-white font-black text-xs uppercase tracking-widest mb-1 block">{feedbackMessage}</span>
                    <span className="text-white text-lg font-bold leading-tight px-2">{instruction}</span>
                </div>
            )}
            <div className="mt-2 text-[8px] text-white/40 font-mono">Phiên: {sessionId}</div>
        </div>

        <div className="flex-1 relative flex items-center justify-center bg-gray-900 overflow-hidden">
            {cameraError ? (
                <div className="text-white text-center p-6 bg-black/80 rounded-2xl border border-red-500 m-4 shadow-2xl max-w-sm">
                    <div className="text-3xl mb-4">📷🚫</div>
                    <p className="font-bold mb-4">{cameraError}</p>
                    <button onClick={() => window.location.reload()} className="px-6 py-3 bg-white text-black rounded-xl font-bold uppercase text-xs hover:bg-gray-200">Thử lại</button>
                </div>
            ) : capturedImage ? (
                <div className="relative h-full w-full flex items-center justify-center p-4">
                    <img src={capturedImage} className="max-h-full max-w-full rounded shadow-2xl" alt="Preview" />
                </div>
            ) : (
                <>
                    <video ref={videoRef} autoPlay playsInline muted className={`absolute inset-0 w-full h-full object-cover ${facingMode === 'user' ? 'transform -scale-x-100' : ''}`} />
                    <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none z-20">
                        <defs><mask id="m"><rect x="0" y="0" width="100" height="100" fill="white" /><ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="black" /></mask></defs>
                        <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#m)" />
                        <ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="none" stroke={overlayColor} strokeWidth="0.5" strokeDasharray="2,2" />
                    </svg>
                </>
            )}

            {countdown !== null && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/40 z-[100] backdrop-blur-sm">
                    <span className="text-9xl font-black text-white animate-ping">{countdown}</span>
                </div>
            )}
        </div>

        <div className="bg-black/95 p-6 pb-12 z-50 flex flex-col items-center gap-4">
            {capturedImage ? (
                <div className="flex w-full gap-4 max-w-sm">
                    <button onClick={() => setCapturedImage(null)} disabled={isUploading} className="flex-1 py-4 bg-gray-800 text-white rounded-2xl font-bold uppercase text-xs">Chụp lại</button>
                    <button onClick={handleUpload} disabled={isUploading} className="flex-[2] py-4 bg-brand-600 text-white rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 uppercase text-xs">
                        {isUploading ? "Đang gửi..." : "Sử dụng ảnh này"}
                    </button>
                </div>
            ) : (
                <div className="flex items-center justify-between w-full max-w-sm px-4">
                    <button onClick={() => setFacingMode(f => f === 'user' ? 'environment' : 'user')} className="w-14 h-14 rounded-full bg-white/20 flex items-center justify-center text-white backdrop-blur border border-white/10 active:bg-white/30 transition-all">
                        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                    </button>

                    <button onClick={() => setCountdown(3)} disabled={countdown !== null} className={`w-24 h-24 rounded-full border-4 flex items-center justify-center transition-all ${validationStatus === 'valid' ? 'border-green-500 bg-white shadow-[0_0_30px_rgba(34,197,94,0.5)]' : 'border-gray-500 bg-gray-700'}`}>
                        <div className={`w-20 h-20 rounded-full transition-colors ${validationStatus === 'valid' ? 'bg-green-600' : 'bg-gray-500'}`}></div>
                    </button>

                    <button onClick={() => setIsAutoCaptureEnabled(!isAutoCaptureEnabled)} className={`w-14 h-14 rounded-xl flex flex-col items-center justify-center border-2 transition-all active:scale-95 ${isAutoCaptureEnabled ? 'bg-brand-600 border-brand-400 text-white shadow-lg shadow-brand-500/50' : 'bg-gray-800 border-gray-600 text-gray-500'}`}>
                        <svg className={`w-6 h-6 mb-0.5 ${isAutoCaptureEnabled ? 'animate-pulse' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                        <span className="text-[9px] font-black uppercase">Auto</span>
                    </button>
                </div>
            )}
        </div>
        <canvas ref={canvasRef} className="hidden" />
        <canvas ref={analysisCanvasRef} className="hidden" />
    </div>
  );
};

export default MobileCaptureClient;

import React, { useState, useEffect, useRef } from 'react';
import { AppConfig, PhotoSize } from '../types';
import { getPhotoById } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCameraLinkProps {
  onPhotoReceived: (dataUrl: string) => void;
  onCancel: () => void;
  config: AppConfig;
  selectedSize: PhotoSize;
}

const MobileCameraLink: React.FC<MobileCameraLinkProps> = ({ onPhotoReceived, onCancel, config, selectedSize }) => {
  const sessionIdRef = useRef<string>(`sid_${Math.random().toString(36).substring(2, 8)}`);
  const [qrUrl, setQrUrl] = useState<string>('');
  const [status, setStatus] = useState<'waiting' | 'found' | 'downloading'>('waiting');
  const [pollCount, setPollCount] = useState(0);

  const isMountedRef = useRef(true);
  const timeoutRef = useRef<any>(null);

  useEffect(() => {
    const sid = sessionIdRef.current;

    // DYNAMIC DETECTION: Get the exact base URL of current deployment
    // Use origin (e.g., https://myapp.run.app) instead of a hardcoded string
    const baseUrl = window.location.origin + window.location.pathname;

    const scriptUrlEncoded = encodeURIComponent(config.googleScriptUrl || '');

    // Create mobile link with current deployment URL
    const mobileLink = `${baseUrl}?mobileSession=${sid}&size=${selectedSize}&surl=${scriptUrlEncoded}`;

    // Generate QR
    setQrUrl(`https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=${encodeURIComponent(mobileLink)}&color=000000&bgcolor=FFFFFF&margin=2&ecc=M`);

    return () => {
        isMountedRef.current = false;
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [selectedSize, config.googleScriptUrl]);

  const pollForPhoto = async () => {
      if (!isMountedRef.current) return;

      try {
          setPollCount(prev => prev + 1);
          const photo = await getPhotoById(sessionIdRef.current, config.googleScriptUrl, true);

          if (photo && photo.dataUrl) {
              if (!isMountedRef.current) return;
              setStatus('found');
              setTimeout(() => {
                  if (isMountedRef.current) {
                      onPhotoReceived(photo.dataUrl);
                  }
              }, 1000);
              return;
          }
      } catch (e) {
          console.error("Polling silent error:", e);
      }

      if (isMountedRef.current) {
          timeoutRef.current = setTimeout(pollForPhoto, 2500);
      }
  };

  useEffect(() => {
      pollForPhoto();
      return () => {
          if (timeoutRef.current) clearTimeout(timeoutRef.current);
      };
  }, []);

  return (
    <div className="absolute inset-0 z-[60] bg-slate-950/95 backdrop-blur-xl flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] shadow-2xl max-w-md w-full relative overflow-hidden border border-white/10">
        <div className={`absolute top-0 left-0 w-full h-1.5 transition-colors duration-500 ${status === 'found' ? 'bg-green-500' : 'bg-brand-500'}`}></div>

        {status === 'found' ? (
            <div className="py-12 animate-pulse flex flex-col items-center">
                <div className="w-24 h-24 bg-green-500 text-white rounded-full flex items-center justify-center mb-6 shadow-green-500/50 shadow-lg">
                    <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7"></path></svg>
                </div>
                <h2 className="text-2xl font-black text-gray-800 dark:text-white uppercase tracking-tight">Đã nhận ảnh!</h2>
                <p className="text-gray-500 mt-2">Đang tải xuống máy tính...</p>
            </div>
        ) : (
            <>
                <div className="mb-6">
                    <h2 className="text-xl font-black text-gray-800 dark:text-white uppercase leading-tight mb-1">Kết nối Điện Thoại</h2>
                    <div className="flex items-center justify-center gap-2">
                        <span className="relative flex h-3 w-3">
                          <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-brand-400 opacity-75"></span>
                          <span className="relative inline-flex rounded-full h-3 w-3 bg-brand-500"></span>
                        </span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                            Đang chờ ảnh từ Cloud... ({pollCount})
                        </span>
                    </div>
                </div>

                <div className="relative mx-auto w-56 h-56 mb-8 p-3 bg-white rounded-2xl shadow-inner border border-gray-100 flex items-center justify-center">
                    {qrUrl ? (
                        <img src={qrUrl} alt="QR Code" className="w-full h-full object-contain" />
                    ) : (
                        <div className="animate-spin w-10 h-10 border-4 border-brand-200 border-t-brand-600 rounded-full"></div>
                    )}

                    <div className="absolute -bottom-12 left-1/2 -translate-x-1/2 w-max">
                        <div className="flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-slate-700 rounded-full text-xs font-bold text-slate-600 dark:text-slate-300 shadow-sm">
                            <span className="text-lg">📸</span> Quét mã để chụp
                        </div>
                    </div>
                </div>

                <div className="space-y-4 mt-8">
                    <div className="bg-slate-50 dark:bg-gray-900/50 p-4 rounded-xl border border-slate-100 dark:border-gray-700 text-left">
                         <div className="flex gap-3 mb-2">
                            <div className="w-6 h-6 rounded-full bg-brand-100 text-brand-600 flex items-center justify-center font-bold text-xs shrink-0">1</div>
                            <p className="text-xs text-slate-600 dark:text-slate-300 pt-0.5">Dùng điện thoại quét mã QR ở trên.</p>
                         </div>
                         <div className="flex gap-3 mb-2">
                            <div className="w-6 h-6 rounded-full bg-brand-100 text-brand-600 flex items-center justify-center font-bold text-xs shrink-0">2</div>
                            <p className="text-xs text-slate-600 dark:text-slate-300 pt-0.5">Chụp ảnh selfie hoặc tải ảnh lên.</p>
                         </div>
                         <div className="flex gap-3">
                            <div className="w-6 h-6 rounded-full bg-brand-100 text-brand-600 flex items-center justify-center font-bold text-xs shrink-0">3</div>
                            <p className="text-xs text-slate-600 dark:text-slate-300 pt-0.5">Nhấn "Sử dụng ảnh", máy tính sẽ tự nhận.</p>
                         </div>
                    </div>

                    <button onClick={onCancel} className="w-full py-3 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-xl font-bold text-[11px] uppercase tracking-wider hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors">
                        Quay lại Webcam
                    </button>
                </div>
            </>
        )}
      </div>
    </div>
  );
};

export default MobileCameraLink;

import React, { useRef, useState, useEffect, useCallback, useMemo } from 'react';
import { PhotoSize, AppConfig } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';
import { savePhotoToCloud } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCaptureClientProps {
  sessionId: string;
  config: AppConfig;
  initialSize?: PhotoSize;
}

type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

const SHUTTER_SOUND = "data:audio/mp3;base64,";

const MobileCaptureClient: React.FC<MobileCaptureClientProps> = ({ sessionId, config, initialSize = PhotoSize.SIZE_4X6 }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null);
  const shutterAudioRef = useRef<HTMLAudioElement | null>(null);
  const analysisIntervalRef = useRef<any>(null);
  const isAnalyzingRef = useRef(false);
  const hasAutoCapturedRef = useRef(false);
  const lastSpokenRef = useRef<string>('');

  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>(t('capture.label.processing', config));
  const [instruction, setInstruction] = useState<string>('');
  const [cameraError, setCameraError] = useState('');
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  // Default to TRUE for Auto Capture as requested
  const [isAutoCaptureEnabled, setIsAutoCaptureEnabled] = useState(true);

  // --- Voice Synthesis Logic ---
  const speak = (text: string, force: boolean = false) => {
    if (!text || (!force && lastSpokenRef.current === text)) return;

    // Mobile synthesis usually requires a user interaction (like a button click) to start
    // We try anyway but it might only work after the first "Capture" or "Retry" click
    if (force || window.speechSynthesis.speaking) window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = config.language === 'en' ? 'en-US' : 'vi-VN'; 

    const voices = window.speechSynthesis.getVoices();
    const voice = voices.find(v => v.lang.startsWith(utterance.lang));
    if (voice) utterance.voice = voice;

    utterance.rate = 1.0; 
    window.speechSynthesis.speak(utterance);
    lastSpokenRef.current = text;
  };

  // Speak instructions on change
  useEffect(() => {
     if (countdown !== null) return; 
     if (instruction) {
         if (validationStatus === 'valid') { 
            if (lastSpokenRef.current !== 'ok') { 
                speak(t('capture.msg.valid', config), true); 
                lastSpokenRef.current = 'ok'; 
            } 
         } else { 
            speak(instruction); 
         }
     }
  }, [instruction, validationStatus, countdown]);

  const startCamera = async (mode: 'user' | 'environment') => {
    // SECURITY CHECK: Browsers block camera on non-secure origins (except localhost)
    if (!window.isSecureContext && window.location.hostname !== 'localhost') {
        setCameraError('LỖI BẢO MẬT: Camera yêu cầu kết nối HTTPS. Hãy kiểm tra lại địa chỉ web.');
        return;
    }

    if (videoRef.current && videoRef.current.srcObject) {
        const stream = videoRef.current.srcObject as MediaStream;
        stream.getTracks().forEach(track => track.stop());
    }

    const constraints: MediaStreamConstraints = { 
        audio: false, // Explicitly false for better compatibility
        video: { 
            facingMode: mode, 
            width: { ideal: 1280 }, 
            height: { ideal: 720 } 
        } 
    };

    try {
      const s = await navigator.mediaDevices.getUserMedia(constraints);
      if (videoRef.current) {
          videoRef.current.srcObject = s;
          // Safari fix: handle play explicitly
          videoRef.current.play().catch(e => console.error("Video play failed:", e));
      }
      setCameraError('');
    } catch (e: any) {
      console.error("Camera access error:", e);
      if (e.name === 'NotAllowedError' || e.name === 'PermissionDeniedError') {
          setCameraError('QUYỀN TRUY CẬP BỊ TỪ CHỐI: Hãy vào cài đặt trình duyệt để cấp quyền Camera.');
      } else {
          setCameraError('MÁY ẢNH KHÔNG SẴN SÀNG: Vui lòng kiểm tra quyền hoặc khởi động lại trình duyệt.');
      }
    }
  };

  useEffect(() => {
    startCamera(facingMode);
    shutterAudioRef.current = new Audio(SHUTTER_SOUND);
    return () => {
      if (videoRef.current && videoRef.current.srcObject) {
          const stream = videoRef.current.srcObject as MediaStream;
          stream.getTracks().forEach(t => t.stop());
      }
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
      window.speechSynthesis.cancel();
    };
  }, [facingMode]);

  useEffect(() => {
    if (videoRef.current?.srcObject && !countdown && !capturedImage) {
      analysisIntervalRef.current = setInterval(performAIAnalysis, 3000);
    } else {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    }
    return () => { if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current); };
  }, [countdown, capturedImage, videoRef.current?.srcObject]);

  useEffect(() => {
    if (isAutoCaptureEnabled && validationStatus === 'valid' && !hasAutoCapturedRef.current && countdown === null && !capturedImage) {
      hasAutoCapturedRef.current = true;
      setCountdown(3);
    } else if (validationStatus !== 'valid') {
      hasAutoCapturedRef.current = false;
    }
  }, [validationStatus, isAutoCaptureEnabled, countdown, capturedImage]);

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current) return;
    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (video.readyState === 4 && ctx) {
        const crop = getCropDimensions(video.videoWidth, video.videoHeight);
        canvas.width = 240; canvas.height = 360;
        if (facingMode === 'user') { ctx.translate(canvas.width, 0); ctx.scale(-1, 1); }
        ctx.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        const result = await analyzeIDPhotoFrame(canvas.toDataURL('image/jpeg', 0.5));
        if (!result.faceDetected) {
            setValidationStatus('searching'); setFeedbackMessage(t('capture.msg.no_face', config)); setInstruction(t('capture.msg.move_in', config));
        } else if (result.isCompliant) {
            setValidationStatus('valid'); setFeedbackMessage(t('capture.status.valid', config)); setInstruction(t('capture.msg.valid', config));
        } else {
            setValidationStatus('adjusting'); setFeedbackMessage(result.feedback || t('capture.status.adjusting', config)); setInstruction(result.instruction || '');
        }
      }
    } catch (err) {} finally { isAnalyzingRef.current = false; }
  };

  const getCropDimensions = (sourceW: number, sourceH: number) => {
    let targetRatio = initialSize === PhotoSize.SIZE_5X5 ? 1 : (initialSize === PhotoSize.SIZE_3X4 ? 3/4 : 2/3);
    const sourceRatio = sourceW / sourceH;
    let cropW, cropH, startX, startY;
    if (sourceRatio > targetRatio) { cropH = sourceH; cropW = cropH * targetRatio; startX = (sourceW - cropW) / 2; startY = 0; }
    else { cropW = sourceW; cropH = cropW / targetRatio; startX = 0; startY = (sourceH - cropH) * 0.5; }
    return { x: Math.floor(startX), y: Math.floor(startY), w: Math.floor(cropW), h: Math.floor(cropH) };
  };

  const captureFrame = useCallback(() => {
    if (shutterAudioRef.current) shutterAudioRef.current.play().catch(() => {});
    if (!videoRef.current || !canvasRef.current) return;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const crop = getCropDimensions(video.videoWidth, video.videoHeight);

    canvas.height = 1200; // Better quality for mobile
    canvas.width = Math.floor(1200 * (crop.w/crop.h));

    if (facingMode === 'user') { ctx?.translate(canvas.width, 0); ctx?.scale(-1, 1); }
    ctx?.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);

    setCapturedImage(canvas.toDataURL('image/jpeg', 0.9));
  }, [facingMode, initialSize]);

  useEffect(() => {
    if (countdown === null) return;
    if (countdown > 0) {
        speak(countdown.toString(), true); 
        const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
        return () => clearTimeout(timer);
    } else {
        captureFrame();
        setCountdown(null);
    }
  }, [countdown, captureFrame]);

  const handleUpload = async () => {
    if (!capturedImage || !sessionId) return;
    setIsUploading(true);
    try {
        const resultId = await savePhotoToCloud({
            id: sessionId,
            dataUrl: capturedImage,
            timestamp: Date.now(),
            settings: { size: initialSize, background: 'original' as any, beauty: {} as any, printQuantity: 1 }
        }, config.googleScriptUrl);

        if (resultId) setIsCompleted(true);
        else alert('Đồng bộ thất bại. Hãy kiểm tra kết nối mạng.');
    } catch (e) { 
        alert('Lỗi khi gửi ảnh lên Cloud.'); 
    } finally { 
        setIsUploading(false); 
    }
  };

  const topMarginPercent = useMemo(() => initialSize === PhotoSize.SIZE_3X4 ? 7.5 : initialSize === PhotoSize.SIZE_5X5 ? 6 : 7, [initialSize]);
  const overlayColor = validationStatus === 'valid' ? '#22c55e' : validationStatus === 'adjusting' ? '#facc15' : '#ef4444';

  if (isCompleted) {
    return (
        <div className="h-[100dvh] bg-brand-600 flex flex-col items-center justify-center text-white p-8 text-center animate-fadeIn">
            <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mb-8 shadow-2xl">
                <svg className="w-10 h-10 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
            </div>
            <h2 className="text-2xl font-black mb-4 uppercase tracking-tighter">Đã gửi ảnh!</h2>
            <p className="opacity-90 text-sm">Ảnh đã được gửi về máy tính chụp ảnh.</p>
            <p className="mt-2 font-mono text-[10px] opacity-60">Session: {sessionId}</p>
            <button onClick={() => window.close()} className="mt-8 px-8 py-3 bg-white/20 border border-white/30 rounded-xl font-bold text-xs">Đóng trang</button>
        </div>
    );
  }

  return (
    <div className="h-[100dvh] bg-black flex flex-col relative overflow-hidden touch-none py-safe">
        <div className="absolute top-0 left-0 right-0 p-4 z-50 flex flex-col items-center pointer-events-none">
            {!capturedImage && (
                <div className={`px-6 py-4 rounded-3xl backdrop-blur-md border-2 transition-all duration-300 text-center shadow-lg flex flex-col items-center max-w-[90%] ${validationStatus === 'valid' ? 'bg-green-600/90 border-green-400' : 'bg-black/60 border-white/20'}`}>
                    <span className="text-white font-black text-[10px] uppercase tracking-widest mb-1 block opacity-70">{feedbackMessage}</span>
                    <span className="text-white text-lg font-bold leading-tight px-2">{instruction || "Đang căn chỉnh..."}</span>
                </div>
            )}
        </div>

        <div className="flex-1 relative flex items-center justify-center bg-gray-950 overflow-hidden">
            {cameraError ? (
                <div className="text-white text-center p-8 bg-black/80 rounded-[2rem] border border-red-500/50 m-6 shadow-2xl max-w-sm">
                    <div className="text-5xl mb-6">📷</div>
                    <p className="font-bold text-sm leading-relaxed mb-8">{cameraError}</p>
                    <button onClick={() => window.location.reload()} className="w-full py-4 bg-white text-black rounded-2xl font-black uppercase text-xs hover:bg-gray-200 transition-colors">Thử lại</button>
                </div>
            ) : capturedImage ? (
                <div className="relative h-full w-full flex items-center justify-center p-4 bg-gray-900">
                    <img src={capturedImage} className="max-h-full max-w-full rounded-lg shadow-2xl border-2 border-white/10" alt="Preview" />
                </div>
            ) : (
                <>
                    <video ref={videoRef} autoPlay playsInline muted className={`absolute inset-0 w-full h-full object-cover ${facingMode === 'user' ? 'transform -scale-x-100' : ''}`} />
                    <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none z-20">
                        <defs><mask id="m"><rect x="0" y="0" width="100" height="100" fill="white" /><ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="black" /></mask></defs>
                        <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#m)" />
                        <ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="none" stroke={overlayColor} strokeWidth="0.5" strokeDasharray="2,2" />
                    </svg>
                </>
            )}

            {countdown !== null && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/40 z-[100] backdrop-blur-sm">
                    <span className="text-[12rem] font-black text-white animate-ping">{countdown}</span>
                </div>
            )}
        </div>

        <div className="bg-black p-6 pb-12 z-50 flex flex-col items-center gap-4">
            {capturedImage ? (
                <div className="flex w-full gap-4 max-w-sm">
                    <button onClick={() => { setCapturedImage(null); hasAutoCapturedRef.current = false; }} disabled={isUploading} className="flex-1 py-4 bg-gray-800 text-white rounded-2xl font-bold uppercase text-xs">Chụp lại</button>
                    <button onClick={handleUpload} disabled={isUploading} className="flex-[2] py-4 bg-brand-600 text-white rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 uppercase text-xs">
                        {isUploading ? <div className="w-4 h-4 border-2 border-white/50 border-t-white rounded-full animate-spin"></div> : "Sử dụng ảnh này"}
                    </button>
                </div>
            ) : (
                <div className="flex items-center justify-between w-full max-w-sm px-4">
                    <button onClick={() => setFacingMode(f => f === 'user' ? 'environment' : 'user')} className="w-14 h-14 rounded-2xl bg-white/10 flex items-center justify-center text-white backdrop-blur border border-white/10 active:bg-white/30 transition-all shadow-lg">
                        <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                    </button>

                    <button onClick={() => setCountdown(3)} disabled={countdown !== null || !!cameraError} className={`w-24 h-24 rounded-full border-4 flex items-center justify-center transition-all active:scale-90 ${validationStatus === 'valid' ? 'border-green-500 bg-white shadow-[0_0_40px_rgba(34,197,94,0.4)]' : 'border-gray-700 bg-gray-900'}`}>
                        <div className={`w-20 h-20 rounded-full transition-colors ${validationStatus === 'valid' ? 'bg-green-600 shadow-inner' : 'bg-gray-800'}`}></div>
                    </button>

                    <button onClick={() => setIsAutoCaptureEnabled(!isAutoCaptureEnabled)} className={`w-14 h-14 rounded-2xl flex flex-col items-center justify-center border-2 transition-all active:scale-95 shadow-lg ${isAutoCaptureEnabled ? 'bg-brand-600 border-brand-400 text-white shadow-brand-500/30' : 'bg-gray-900 border-gray-700 text-gray-500'}`}>
                        <svg className={`w-6 h-6 mb-0.5 ${isAutoCaptureEnabled ? 'animate-pulse' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                        <span className="text-[8px] font-black uppercase">Auto</span>
                    </button>
                </div>
            )}
        </div>
        <canvas ref={canvasRef} className="hidden" />
        <canvas ref={analysisCanvasRef} className="hidden" />
    </div>
  );
};

export default MobileCaptureClient;

import React, { useEffect, useState } from 'react';
import { getPhotoById } from '../services/databaseService';
import { SavedPhoto, PhotoSize, AppConfig } from '../types';

interface PhotoViewerProps {
  photoId: string;
  config?: AppConfig; // Optional config for branding
}

const PhotoViewer: React.FC<PhotoViewerProps> = ({ photoId, config }) => {
  const [photo, setPhoto] = useState<SavedPhoto | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Sheet Generation State
  const [isGenerating, setIsGenerating] = useState(false);

  // Determine current URL for QR
  const getCurrentUrl = () => {
    // DYNAMIC DETECTION
    const baseUrl = window.location.origin + window.location.pathname;
    return `${baseUrl}?photoId=${photoId}`;
  };

  useEffect(() => {
    const fetchPhoto = async () => {
      setLoading(true);
      const data = await getPhotoById(photoId);
      if (data) {
        setPhoto(data);
      } else {
        setError('Không tìm thấy ảnh hoặc ảnh đã bị xóa.');
      }
      setLoading(false);
    };
    fetchPhoto();
  }, [photoId]);

  // --- DOWNLOAD HANDLERS ---
  const downloadImage = (dataUrl: string, filename: string) => {
    const link = document.createElement('a');
    link.href = dataUrl;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadSingle = () => {
    if (!photo) return;
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = photo.dataUrl;
    img.crossOrigin = "anonymous";
    img.onload = () => {
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            ctx.drawImage(img, 0, 0);
            const pngData = canvas.toDataURL('image/png');
            downloadImage(pngData, `Photo-${photo.id}-Single.png`);
        }
    };
  };

  // Helper to load image for Canvas
  const loadImage = (src: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error(`Failed to load image`));
        img.src = src;
    });
  };

  const handleDownloadSheet = async () => {
    if (!photo) return;
    setIsGenerating(true);

    try {
        // CONFIG CONSTANTS
        const DPI = 300;
        const MM_TO_PX = DPI / 25.4;
        const SHEET_W = Math.ceil(130 * MM_TO_PX);
        const SHEET_H = Math.ceil(180 * MM_TO_PX);

        const canvas = document.createElement('canvas');
        canvas.width = SHEET_W;
        canvas.height = SHEET_H;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error("Canvas init failed");

        // 1. Fill White Background
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // 2. Prepare Resources
        const photoUrl = photo.dataUrl;
        const shopLogoUrl = config?.logoUrl;
        const qrContent = getCurrentUrl();
        const qrApiUrl = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(qrContent)}&color=000000&bgcolor=FFFFFF&margin=0&ecc=H`;

        const [mainPhotoImg, logoImg, qrImg] = await Promise.all([
            loadImage(photoUrl),
            shopLogoUrl ? loadImage(shopLogoUrl).catch(() => null) : Promise.resolve(null),
            loadImage(qrApiUrl).catch(() => null)
        ]);

        // 3. Draw Photo Grid
        const size = photo.settings.size;
        let cols=2, rows=4, photoW_mm=60, photoH_mm=40, rotated=true, maxOnSheet=8;

        if (size === PhotoSize.SIZE_3X4) {
            cols = 4; rows = 4; photoW_mm = 30; photoH_mm = 40; rotated = false; maxOnSheet = 16;
        } else if (size === PhotoSize.SIZE_5X5) {
            cols = 2; rows = 3; photoW_mm = 50; photoH_mm = 50; rotated = false; maxOnSheet = 6;
        }

        const cellW = photoW_mm * MM_TO_PX;
        const cellH = photoH_mm * MM_TO_PX;
        const gridW = cols * cellW;
        const startY = 5 * MM_TO_PX; 
        const startX = (canvas.width - gridW) / 2;

        for (let i = 0; i < maxOnSheet; i++) {
            const r = Math.floor(i / cols);
            const c = i % cols;
            const x = startX + c * cellW;
            const y = startY + r * cellH;

            ctx.save();
            ctx.beginPath();
            ctx.rect(x, y, cellW, cellH);
            ctx.clip();

            if (rotated) {
                const cx = x + cellW / 2;
                const cy = y + cellH / 2;
                ctx.translate(cx, cy);
                ctx.rotate(-90 * Math.PI / 180);
                ctx.drawImage(mainPhotoImg, -cellH/2, -cellW/2, cellH, cellW); 
            } else {
                ctx.drawImage(mainPhotoImg, x, y, cellW, cellH);
            }
            ctx.restore();

            ctx.strokeStyle = '#d1d5db';
            ctx.lineWidth = 1;
            ctx.setLineDash([15, 15]);
            ctx.strokeRect(x, y, cellW, cellH);
        }

        // 4. Draw Footer
        const footerH = 15 * MM_TO_PX; 
        const footerY = canvas.height - footerH;

        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, footerY, canvas.width, footerH);

        ctx.beginPath();
        ctx.moveTo(0, footerY);
        ctx.lineTo(canvas.width, footerY);
        ctx.strokeStyle = '#000000';
        ctx.lineWidth = 2;
        ctx.setLineDash([]);
        ctx.stroke();

        const padding = 5 * MM_TO_PX;
        const contentY = footerY + footerH / 2;
        let leftOffset = padding;

        if (logoImg) {
            const logoH = 10 * MM_TO_PX; 
            const scale = logoH / logoImg.height;
            const logoW = logoImg.width * scale;
            const logoY = contentY - logoH / 2;

            ctx.drawImage(logoImg, leftOffset, logoY, logoW, logoH);
            leftOffset += logoW + (3 * MM_TO_PX); 
        }

        ctx.textAlign = 'left';
        ctx.fillStyle = '#000000';
        const nameSize = 5 * MM_TO_PX;
        ctx.font = `bold ${nameSize}px sans-serif`;
        ctx.textBaseline = 'bottom';
        const shopName = config?.shopName || "ID Photo Booth";
        ctx.fillText(shopName, leftOffset, contentY - (0.5 * MM_TO_PX));

        ctx.fillStyle = '#4b5563';
        const infoSize = 3.5 * MM_TO_PX;
        ctx.font = `${infoSize}px sans-serif`;
        ctx.textBaseline = 'top';
        const dateStr = new Date(photo.timestamp).toLocaleDateString('vi-VN');
        const footerText = config?.printFooterText || "Ảnh thẻ lấy ngay";
        ctx.fillText(`${footerText} | ${dateStr}`, leftOffset, contentY + (0.5 * MM_TO_PX));

        if (qrImg) {
            const qrSize = 12 * MM_TO_PX; 
            const qrX = canvas.width - padding - qrSize;
            const qrY = contentY - qrSize / 2;
            ctx.drawImage(qrImg, qrX, qrY, qrSize, qrSize);
            if (logoImg) {
                const centerLogoSize = qrSize * 0.25; 
                const centerX = qrX + (qrSize - centerLogoSize) / 2;
                const centerY = qrY + (qrSize - centerLogoSize) / 2;
                ctx.fillStyle = '#ffffff';
                ctx.fillRect(centerX - 1, centerY - 1, centerLogoSize + 2, centerLogoSize + 2);
                ctx.drawImage(logoImg, centerX, centerY, centerLogoSize, centerLogoSize);
            }
        }

        const sheetDataUrl = canvas.toDataURL('image/png');
        downloadImage(sheetDataUrl, `Photo-${photo.id}-Sheet-13x18.png`);

    } catch (e) {
        console.error("Sheet generation failed", e);
        alert("Không thể tạo file in. Vui lòng thử lại.");
    } finally {
        setIsGenerating(false);
    }
  };

  if (loading) return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-gray-50 p-4">
        <div className="w-12 h-12 border-4 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-4"></div>
        <p className="text-gray-500 font-medium animate-pulse">Đang tải ảnh từ Cloud...</p>
    </div>
  );

  if (error || !photo) return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-gray-50 p-6 text-center">
        <div className="w-16 h-16 bg-red-100 text-red-500 rounded-full flex items-center justify-center mb-4 shadow-sm">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
        </div>
        <h2 className="text-xl font-bold text-gray-800 mb-2">Không tìm thấy ảnh</h2>
        <p className="text-gray-600 mb-6 max-w-xs mx-auto">{error}</p>
        <a href="/" className="px-6 py-2.5 bg-gray-800 text-white rounded-xl font-bold hover:bg-black transition shadow-lg">Về trang chủ</a>
    </div>
  );

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-200 p-4 flex flex-col items-center">
       <div className="mb-4 md:mb-6 flex flex-col items-center animate-fadeIn">
          {config?.logoUrl ? (
             <img src={config.logoUrl} alt="Logo" className="h-12 md:h-16 w-auto object-contain mb-2 drop-shadow-sm" />
          ) : (
             <div className="w-10 h-10 md:w-12 md:h-12 bg-brand-600 rounded-2xl flex items-center justify-center text-white font-bold text-lg md:text-xl mb-2 shadow-lg">
               {config?.shopName?.charAt(0) || 'P'}
             </div>
          )}
          <span className="font-bold text-lg md:text-xl text-slate-800 text-center">{config?.shopName || 'ID Photo Booth'}</span>
       </div>

       <div className="max-w-4xl w-full bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row animate-fadeIn">
          <div className="w-full md:w-1/2 bg-slate-100 p-6 md:p-8 flex flex-col items-center justify-center border-b md:border-b-0 md:border-r border-slate-200 relative">
             <div className="absolute top-4 left-4 bg-white/80 backdrop-blur px-3 py-1 rounded-full text-xs font-bold text-slate-500 shadow-sm">
                ID: {photo.id}
             </div>
             <div className="relative shadow-2xl rounded-lg overflow-hidden border-4 border-white transform transition hover:scale-105 duration-300">
