import React, { useRef, useState, useEffect, useCallback, useMemo } from 'react';
import { PhotoSize, AppConfig } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';
import { savePhotoToCloud } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCaptureClientProps {
  sessionId: string;
  config: AppConfig;
  initialSize?: PhotoSize;
}

type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

const SHUTTER_SOUND = "data:audio/mp3;base64,";

const MobileCaptureClient: React.FC<MobileCaptureClientProps> = ({ sessionId, config, initialSize = PhotoSize.SIZE_4X6 }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null);
  const shutterAudioRef = useRef<HTMLAudioElement | null>(null);
  const analysisIntervalRef = useRef<any>(null);
  const isAnalyzingRef = useRef(false);
  const hasAutoCapturedRef = useRef(false);
  const lastSpokenRef = useRef<string>('');

  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>(t('capture.label.processing', config));
  const [instruction, setInstruction] = useState<string>('');
  const [cameraError, setCameraError] = useState('');
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  const [isAutoCaptureEnabled, setIsAutoCaptureEnabled] = useState(true);

  // --- Voice Synthesis Logic ---
  const speak = (text: string, force: boolean = false) => {
    if (!text || (!force && lastSpokenRef.current === text)) return;
    if (force || window.speechSynthesis.speaking) window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = config.language === 'en' ? 'en-US' : 'vi-VN'; 
    const voices = window.speechSynthesis.getVoices();
    const voice = voices.find(v => v.lang.startsWith(utterance.lang));
    if (voice) utterance.voice = voice;
    utterance.rate = 1.0; 
    window.speechSynthesis.speak(utterance);
    lastSpokenRef.current = text;
  };

  useEffect(() => {
     if (countdown !== null) return; 
     if (instruction) {
         if (validationStatus === 'valid') { 
            if (lastSpokenRef.current !== 'ok') { 
                speak(t('capture.msg.valid', config), true); 
                lastSpokenRef.current = 'ok'; 
            } 
         } else { 
            speak(instruction); 
         }
     }
  }, [instruction, validationStatus, countdown]);

  const startCamera = async (mode: 'user' | 'environment') => {
    if (!window.isSecureContext && window.location.hostname !== 'localhost') {
        setCameraError('LỖI BẢO MẬT: Camera yêu cầu kết nối HTTPS.');
        return;
    }

    if (videoRef.current && videoRef.current.srcObject) {
        const stream = videoRef.current.srcObject as MediaStream;
        stream.getTracks().forEach(track => track.stop());
    }

    const constraints: MediaStreamConstraints = { 
        audio: false, 
        video: { 
            facingMode: mode, 
            width: { ideal: 1280 }, 
            height: { ideal: 720 } 
        } 
    };

    try {
      const s = await navigator.mediaDevices.getUserMedia(constraints);
      if (videoRef.current) {
          videoRef.current.srcObject = s;
          videoRef.current.play().catch(e => console.error("Video play failed:", e));
      }
      setCameraError('');
    } catch (e: any) {
      console.error("Camera access error:", e);
      setCameraError('Không thể truy cập Camera. Hãy cấp quyền trong cài đặt trình duyệt.');
    }
  };

  useEffect(() => {
    startCamera(facingMode);
    shutterAudioRef.current = new Audio(SHUTTER_SOUND);
    return () => {
      if (videoRef.current && videoRef.current.srcObject) {
          const stream = videoRef.current.srcObject as MediaStream;
          stream.getTracks().forEach(t => t.stop());
      }
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
      window.speechSynthesis.cancel();
    };
  }, [facingMode]);

  useEffect(() => {
    if (videoRef.current?.srcObject && !countdown && !capturedImage) {
      analysisIntervalRef.current = setInterval(performAIAnalysis, 3000);
    } else {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    }
    return () => { if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current); };
  }, [countdown, capturedImage, videoRef.current?.srcObject]);

  useEffect(() => {
    if (isAutoCaptureEnabled && validationStatus === 'valid' && !hasAutoCapturedRef.current && countdown === null && !capturedImage) {
      hasAutoCapturedRef.current = true;
      setCountdown(3);
    } else if (validationStatus !== 'valid') {
      hasAutoCapturedRef.current = false;
    }
  }, [validationStatus, isAutoCaptureEnabled, countdown, capturedImage]);

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current) return;
    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (video.readyState === 4 && ctx) {
        const crop = getCropDimensions(video.videoWidth, video.videoHeight);
        canvas.width = 240; canvas.height = 360;
        if (facingMode === 'user') { ctx.translate(canvas.width, 0); ctx.scale(-1, 1); }
        ctx.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        const result = await analyzeIDPhotoFrame(canvas.toDataURL('image/jpeg', 0.5));
        if (!result.faceDetected) {
            setValidationStatus('searching'); setFeedbackMessage(t('capture.msg.no_face', config)); setInstruction(t('capture.msg.move_in', config));
        } else if (result.isCompliant) {
            setValidationStatus('valid'); setFeedbackMessage(t('capture.status.valid', config)); setInstruction(t('capture.msg.valid', config));
        } else {
            setValidationStatus('adjusting'); setFeedbackMessage(result.feedback || t('capture.status.adjusting', config)); setInstruction(result.instruction || '');
        }
      }
    } catch (err) {} finally { isAnalyzingRef.current = false; }
  };

  const getCropDimensions = (sourceW: number, sourceH: number) => {
    let targetRatio = initialSize === PhotoSize.SIZE_5X5 ? 1 : (initialSize === PhotoSize.SIZE_3X4 ? 3/4 : 2/3);
    const sourceRatio = sourceW / sourceH;
    let cropW, cropH, startX, startY;
    if (sourceRatio > targetRatio) { cropH = sourceH; cropW = cropH * targetRatio; startX = (sourceW - cropW) / 2; startY = 0; }
    else { cropW = sourceW; cropH = cropW / targetRatio; startX = 0; startY = (sourceH - cropH) * 0.5; }
    return { x: Math.floor(startX), y: Math.floor(startY), w: Math.floor(cropW), h: Math.floor(cropH) };
  };

  const captureFrame = useCallback(() => {
    if (shutterAudioRef.current) shutterAudioRef.current.play().catch(() => {});
    if (!videoRef.current || !canvasRef.current) return;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const crop = getCropDimensions(video.videoWidth, video.videoHeight);

    // SWITCH TO JPEG 0.95: High Quality but significantly smaller size than PNG
    // This fixes the "Upload success but sync fail" issue due to payload size limits
    canvas.height = 1280; 
    canvas.width = Math.floor(1280 * (crop.w/crop.h));

    if (facingMode === 'user') { ctx?.translate(canvas.width, 0); ctx?.scale(-1, 1); }
    ctx?.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);

    // IMPORTANT: image/jpeg at 0.95 quality is visually identical to PNG for printing 
    // but ensures the base64 string is manageable for the cloud sync.
    setCapturedImage(canvas.toDataURL('image/jpeg', 0.95));
  }, [facingMode, initialSize]);

  useEffect(() => {
    if (countdown === null) return;
    if (countdown > 0) {
        speak(countdown.toString(), true); 
        const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
        return () => clearTimeout(timer);
    } else {
        captureFrame();
        setCountdown(null);
    }
  }, [countdown, captureFrame]);

  const handleUpload = async () => {
    if (!capturedImage || !sessionId) return;
    setIsUploading(true);

    const attemptUpload = async (retriesLeft: number): Promise<boolean> => {
        try {
            const resultId = await savePhotoToCloud({
                id: sessionId,
                dataUrl: capturedImage,
                timestamp: Date.now(),
                settings: { size: initialSize, background: 'original' as any, beauty: {} as any, printQuantity: 1 }
            }, config.googleScriptUrl);
            return !!resultId;
        } catch (e) {
            console.error("Upload attempt failed", e);
            if (retriesLeft > 0) {
                await new Promise(r => setTimeout(r, 1000));
                return attemptUpload(retriesLeft - 1);
            }
            return false;
        }
    };

    try {
        const success = await attemptUpload(3); // Retry 3 times
        if (success) {
            setIsCompleted(true);
        } else {
            alert('Không thể gửi ảnh. Mạng yếu hoặc ảnh quá lớn. Hãy thử chụp lại ở nơi sóng tốt hơn.');
        }
    } finally { 
        setIsUploading(false); 
    }
  };

  const topMarginPercent = useMemo(() => initialSize === PhotoSize.SIZE_3X4 ? 7.5 : initialSize === PhotoSize.SIZE_5X5 ? 6 : 7, [initialSize]);
  const overlayColor = validationStatus === 'valid' ? '#22c55e' : validationStatus === 'adjusting' ? '#facc15' : '#ef4444';

  if (isCompleted) {
    return (
        <div className="h-[100dvh] bg-brand-600 flex flex-col items-center justify-center text-white p-8 text-center animate-fadeIn">
            <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mb-8 shadow-2xl">
                <svg className="w-10 h-10 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
            </div>
            <h2 className="text-2xl font-black mb-4 uppercase tracking-tighter">Đã gửi ảnh!</h2>
            <p className="opacity-90 text-sm">Ảnh đã được gửi về máy tính chụp ảnh.</p>
            <p className="mt-2 font-mono text-[10px] opacity-60">Session: {sessionId}</p>
            <button onClick={() => window.close()} className="mt-8 px-8 py-3 bg-white/20 border border-white/30 rounded-xl font-bold text-xs">Đóng trang</button>
        </div>
    );
  }

  return (
    <div className="h-[100dvh] bg-black flex flex-col relative overflow-hidden touch-none py-safe">
        <div className="absolute top-0 left-0 right-0 p-4 z-50 flex flex-col items-center pointer-events-none">
            {!capturedImage && (
                <div className={`px-6 py-4 rounded-3xl backdrop-blur-md border-2 transition-all duration-300 text-center shadow-lg flex flex-col items-center max-w-[90%] ${validationStatus === 'valid' ? 'bg-green-600/90 border-green-400' : 'bg-black/60 border-white/20'}`}>
                    <span className="text-white font-black text-[10px] uppercase tracking-widest mb-1 block opacity-70">{feedbackMessage}</span>
                    <span className="text-white text-lg font-bold leading-tight px-2">{instruction || "Đang căn chỉnh..."}</span>
                </div>
            )}
        </div>

        <div className="flex-1 relative flex items-center justify-center bg-gray-950 overflow-hidden">
            {cameraError ? (
                <div className="text-white text-center p-8 bg-black/80 rounded-[2rem] border border-red-500/50 m-6 shadow-2xl max-w-sm">
                    <div className="text-5xl mb-6">📷</div>
                    <p className="font-bold text-sm leading-relaxed mb-8">{cameraError}</p>
                    <button onClick={() => window.location.reload()} className="w-full py-4 bg-white text-black rounded-2xl font-black uppercase text-xs hover:bg-gray-200 transition-colors">Thử lại</button>
                </div>
            ) : capturedImage ? (
                <div className="relative h-full w-full flex items-center justify-center p-4 bg-gray-900">
                    <img src={capturedImage} className="max-h-full max-w-full rounded-lg shadow-2xl border-2 border-white/10" alt="Preview" />
                </div>
            ) : (
                <>
                    <video ref={videoRef} autoPlay playsInline muted className={`absolute inset-0 w-full h-full object-cover ${facingMode === 'user' ? 'transform -scale-x-100' : ''}`} />
                    <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none z-20">
                        <defs><mask id="m"><rect x="0" y="0" width="100" height="100" fill="white" /><ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="black" /></mask></defs>
                        <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#m)" />
                        <ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="none" stroke={overlayColor} strokeWidth="0.5" strokeDasharray="2,2" />
                    </svg>
                </>
            )}

            {countdown !== null && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/40 z-[100] backdrop-blur-sm">
                    <span className="text-[12rem] font-black text-white animate-ping">{countdown}</span>
                </div>
            )}
        </div>

        <div className="bg-black p-6 pb-12 z-50 flex flex-col items-center gap-4">
            {capturedImage ? (
                <div className="flex w-full gap-4 max-w-sm">
                    <button onClick={() => { setCapturedImage(null); hasAutoCapturedRef.current = false; }} disabled={isUploading} className="flex-1 py-4 bg-gray-800 text-white rounded-2xl font-bold uppercase text-xs">Chụp lại</button>
                    <button onClick={handleUpload} disabled={isUploading} className="flex-[2] py-4 bg-brand-600 text-white rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 uppercase text-xs">
                        {isUploading ? <div className="w-4 h-4 border-2 border-white/50 border-t-white rounded-full animate-spin"></div> : "Sử dụng ảnh này"}
                    </button>
                </div>
            ) : (
                <div className="flex items-center justify-between w-full max-w-sm px-4">
                    <button onClick={() => setFacingMode(f => f === 'user' ? 'environment' : 'user')} className="w-14 h-14 rounded-2xl bg-white/10 flex items-center justify-center text-white backdrop-blur border border-white/10 active:bg-white/30 transition-all shadow-lg">
                        <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                    </button>

                    <button onClick={() => setCountdown(3)} disabled={countdown !== null || !!cameraError} className={`w-24 h-24 rounded-full border-4 flex items-center justify-center transition-all active:scale-90 ${validationStatus === 'valid' ? 'border-green-500 bg-white shadow-[0_0_40px_rgba(34,197,94,0.4)]' : 'border-gray-700 bg-gray-900'}`}>
                        <div className={`w-20 h-20 rounded-full transition-colors ${validationStatus === 'valid' ? 'bg-green-600 shadow-inner' : 'bg-gray-800'}`}></div>
                    </button>

                    <button onClick={() => setIsAutoCaptureEnabled(!isAutoCaptureEnabled)} className={`w-14 h-14 rounded-2xl flex flex-col items-center justify-center border-2 transition-all active:scale-95 shadow-lg ${isAutoCaptureEnabled ? 'bg-brand-600 border-brand-400 text-white shadow-brand-500/30' : 'bg-gray-900 border-gray-700 text-gray-500'}`}>
                        <svg className={`w-6 h-6 mb-0.5 ${isAutoCaptureEnabled ? 'animate-pulse' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                        <span className="text-[8px] font-black uppercase">Auto</span>
                    </button>
                </div>
            )}
        </div>
        <canvas ref={canvasRef} className="hidden" />
        <canvas ref={analysisCanvasRef} className="hidden" />
    </div>
  );
};

export default MobileCaptureClient;

import { SavedPhoto, AppConfig } from "../types";
import { getConfig } from "./configService";

const getScriptUrl = (overrideUrl?: string) => {
    if (overrideUrl && overrideUrl.trim() !== '') return overrideUrl.trim();
    const config = getConfig();
    return (config.googleScriptUrl || '').trim();
};

const callAppsScript = async (action: string, payload: any = {}, overrideUrl?: string): Promise<any> => {
    const url = getScriptUrl(overrideUrl);
    if (!url) {
        console.error(`Apps Script Error: Missing URL for [${action}]`);
        return { success: false, error: "Missing URL" };
    }

    try {
        const body = JSON.stringify({ 
            action, 
            ...payload, 
            _t: Date.now() 
        });

        const response = await fetch(url, {
            method: 'POST',
            body: body,
            // Critical for mobile stability
            keepalive: true,
            // Prevent caching of responses
            cache: 'no-store', 
            headers: { 'Content-Type': 'text/plain;charset=utf-8' }
        });

        if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
        }

        const data = await response.json();
        return data;
    } catch (error) {
        console.error(`Apps Script Network Error [${action}]:`, error);
        return { success: false, error: String(error) };
    }
};

export const savePhotoToCloud = async (photo: SavedPhoto, overrideUrl?: string): Promise<string | null> => {
    const result = await callAppsScript('savePhoto', {
        id: photo.id,
        dataUrl: photo.dataUrl,
        settings: photo.settings
    }, overrideUrl);
    return (result && result.success) ? result.id : null;
};

export const getPhotoById = async (id: string, overrideUrl?: string, skipRetry: boolean = false): Promise<SavedPhoto | null> => {
    const maxRetries = skipRetry ? 1 : 5;

    for (let i = 0; i < maxRetries; i++) {
        const result = await callAppsScript('getPhoto', { id }, overrideUrl);
        if (result && result.success && result.photo) {
            return result.photo as SavedPhoto;
        }

        if (i < maxRetries - 1) {
            await new Promise(r => setTimeout(r, 2000));
        }
    }
    return null;
};

export const saveAppConfigToCloud = async (config: AppConfig): Promise<boolean> => {
    const result = await callAppsScript('saveConfig', { config });
    return !!(result && result.success);
};

export const getAppConfigFromCloud = async (): Promise<AppConfig | null> => {
    const result = await callAppsScript('getConfig');
    return (result && result.success) ? result.config : null;
};

export const getPhotosFromCloud = async (): Promise<SavedPhoto[]> => {
    const result = await callAppsScript('listPhotos');
    if (result && result.success && Array.isArray(result.photos)) {
        return result.photos;
    }
    return [];
};

export const deletePhotoFromCloud = async (id: string, adminPassword?: string): Promise<boolean> => {
    const result = await callAppsScript('deletePhoto', { id, password: adminPassword });
    return !!(result && result.success);
};

import React, { useState, useEffect, useRef } from 'react';
import { AppConfig, PhotoSize } from '../types';
import { getPhotoById } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCameraLinkProps {
  onPhotoReceived: (dataUrl: string) => void;
  onCancel: () => void;
  config: AppConfig;
  selectedSize: PhotoSize;
}

const MobileCameraLink: React.FC<MobileCameraLinkProps> = ({ onPhotoReceived, onCancel, config, selectedSize }) => {
  const sessionIdRef = useRef<string>(`sid_${Math.random().toString(36).substring(2, 8)}`);
  const [qrUrl, setQrUrl] = useState<string>('');
  const [status, setStatus] = useState<'waiting' | 'found' | 'downloading'>('waiting');
  const [pollCount, setPollCount] = useState(0);

  const isMountedRef = useRef(true);
  const timeoutRef = useRef<any>(null);

  useEffect(() => {
    const sid = sessionIdRef.current;

    // Dynamic detection for QR URL
    const baseUrl = window.location.origin + window.location.pathname;
    const scriptUrlEncoded = encodeURIComponent(config.googleScriptUrl || '');
    const mobileLink = `${baseUrl}?mobileSession=${sid}&size=${selectedSize}&surl=${scriptUrlEncoded}`;

    setQrUrl(`https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=${encodeURIComponent(mobileLink)}&color=000000&bgcolor=FFFFFF&margin=2&ecc=M`);

    return () => {
        isMountedRef.current = false;
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [selectedSize, config.googleScriptUrl]);

  const pollForPhoto = async () => {
      if (!isMountedRef.current) return;

      try {
          setPollCount(prev => prev + 1);
          // Try to fetch
          const photo = await getPhotoById(sessionIdRef.current, config.googleScriptUrl, true);

          if (photo && photo.dataUrl) {
              if (!isMountedRef.current) return;

              setStatus('found');

              // Indicate downloading success visually
              setTimeout(() => {
                  if (isMountedRef.current) {
                      onPhotoReceived(photo.dataUrl);
                  }
              }, 500);
              return; 
          }
      } catch (e) {
          console.error("Polling error:", e);
      }

      if (isMountedRef.current) {
          timeoutRef.current = setTimeout(pollForPhoto, 2500);
      }
  };

  useEffect(() => {
      pollForPhoto();
      return () => {
          if (timeoutRef.current) clearTimeout(timeoutRef.current);
      };
  }, []);

  return (
    <div className="absolute inset-0 z-[60] bg-slate-950/95 backdrop-blur-xl flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] shadow-2xl max-w-md w-full relative overflow-hidden border border-white/10">
        <div className={`absolute top-0 left-0 w-full h-1.5 transition-colors duration-500 ${status === 'found' ? 'bg-green-500' : 'bg-brand-500'}`}></div>

        {status === 'found' ? (
            <div className="py-12 animate-pulse flex flex-col items-center">
                <div className="w-24 h-24 bg-green-500 text-white rounded-full flex items-center justify-center mb-6 shadow-green-500/50 shadow-lg">
                    <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7"></path></svg>
                </div>
                <h2 className="text-2xl font-black text-gray-800 dark:text-white uppercase tracking-tight">Đã nhận ảnh!</h2>
                <p className="text-gray-500 mt-2">Đang xử lý dữ liệu...</p>
            </div>
        ) : (
            <>
                <div className="mb-6">
                    <h2 className="text-xl font-black text-gray-800 dark:text-white uppercase leading-tight mb-1">Kết nối Điện Thoại</h2>
                    <div className="flex items-center justify-center gap-2">
                        <span className="relative flex h-3 w-3">
                          <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-brand-400 opacity-75"></span>
                          <span className="relative inline-flex rounded-full h-3 w-3 bg-brand-500"></span>
                        </span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                            Đang chờ ảnh từ Cloud... ({pollCount})
                        </span>
                    </div>
                </div>

                <div className="relative mx-auto w-56 h-56 mb-8 p-3 bg-white rounded-2xl shadow-inner border border-gray-100 flex items-center justify-center">
                    {qrUrl ? (
                        <img src={qrUrl} alt="QR Code" className="w-full h-full object-contain" />
                    ) : (
                        <div className="animate-spin w-10 h-10 border-4 border-brand-200 border-t-brand-600 rounded-full"></div>
                    )}

                    <div className="absolute -bottom-12 left-1/2 -translate-x-1/2 w-max">
                        <div className="flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-slate-700 rounded-full text-xs font-bold text-slate-600 dark:text-slate-300 shadow-sm">
                            <span className="text-lg">📸</span> Quét mã để chụp
                        </div>
                    </div>
                </div>

                <div className="space-y-4 mt-8">
                    <div className="bg-slate-50 dark:bg-gray-900/50 p-4 rounded-xl border border-slate-100 dark:border-gray-700 text-left">
                         <div className="flex gap-3 mb-2">
                            <div className="w-6 h-6 rounded-full bg-brand-100 text-brand-600 flex items-center justify-center font-bold text-xs shrink-0">1</div>
                            <p className="text-xs text-slate-600 dark:text-slate-300 pt-0.5">Dùng điện thoại quét mã QR ở trên.</p>
                         </div>
                         <div className="flex gap-3 mb-2">
                            <div className="w-6 h-6 rounded-full bg-brand-100 text-brand-600 flex items-center justify-center font-bold text-xs shrink-0">2</div>
                            <p className="text-xs text-slate-600 dark:text-slate-300 pt-0.5">Chụp ảnh selfie hoặc tải ảnh lên.</p>
                         </div>
                         <div className="flex gap-3">
                            <div className="w-6 h-6 rounded-full bg-brand-100 text-brand-600 flex items-center justify-center font-bold text-xs shrink-0">3</div>
                            <p className="text-xs text-slate-600 dark:text-slate-300 pt-0.5">Nhấn "Sử dụng ảnh", máy tính sẽ tự nhận.</p>
                         </div>
                    </div>

                    <button onClick={onCancel} className="w-full py-3 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-xl font-bold text-[11px] uppercase tracking-wider hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors">
                        Quay lại Webcam
                    </button>
                </div>
            </>
        )}
      </div>
    </div>
  );
};

export default MobileCameraLink;
